window.QB_TWK_B23 = [
{"id":"TWK-3301","q":"Bunyi sila pertama Pancasila adalah ....","opts":["Ketuhanan Yang Maha Esa","Kemanusiaan yang adil dan beradab","Persatuan Indonesia","Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan","Keadilan sosial bagi seluruh rakyat Indonesia"],"a":0,"ex":"Sila pertama Pancasila berbunyi 'Ketuhanan Yang Maha Esa', menempati posisi teratas sebagai sumber nilai bagi sila-sila lainnya."},
{"id":"TWK-3302","q":"Makna yang terkandung dalam sila pertama Pancasila adalah ....","opts":["bangsa Indonesia mengakui adanya Tuhan dan menjamin kebebasan beragama","negara menentukan satu agama resmi bagi seluruh rakyat","ibadah hanya boleh dilakukan di tempat ibadah yang terdaftar","urusan agama sepenuhnya dipisahkan dari kehidupan bernegara","setiap warga wajib memeluk agama yang sama"],"a":0,"ex":"Sila pertama menegaskan pengakuan terhadap Tuhan Yang Maha Esa sekaligus jaminan kebebasan memeluk agama dan beribadah menurut keyakinannya masing-masing."},
{"id":"TWK-3303","q":"Contoh pengamalan sila pertama Pancasila dalam kehidupan sehari-hari adalah ....","opts":["menghormati teman yang sedang menjalankan ibadah sesuai agamanya","memaksa tetangga mengikuti cara beribadah yang kita yakini","mengejek ritual keagamaan suku lain yang berbeda","melarang pembangunan rumah ibadah agama minoritas","menganggap ajaran agama sendiri paling benar dan merendahkan yang lain"],"a":0,"ex":"Menghormati pelaksanaan ibadah pemeluk agama lain adalah wujud nyata pengamalan sila pertama: toleransi beragama."},
{"id":"TWK-3304","q":"Perilaku berikut yang bertentangan dengan sila pertama Pancasila adalah ....","opts":["melakukan kekerasan atas nama agama terhadap kelompok lain","berdoa sebelum memulai aktivitas belajar di kelas","ikut serta dalam kegiatan bakti sosial lintas agama","menjenguk tetangga sakit tanpa membedakan agamanya","mempelajari kitab suci agamanya dengan tekun"],"a":0,"ex":"Kekerasan atas nama agama jelas menodai sila pertama yang menuntut ketuhanan diwujudkan lewat kasih sayang, bukan kebencian."},
{"id":"TWK-3305","q":"Sila pertama Pancasila disebut menjiwai keempat sila lainnya. Maksud pernyataan tersebut adalah ....","opts":["nilai Ketuhanan menjadi landasan moral bagi pelaksanaan sila-sila yang lain","sila pertama lebih penting sehingga sila lain boleh diabaikan","hanya sila pertama yang wajib diamalkan warga negara","sila-sila lain tidak memiliki kaitan dengan nilai agama","pengamalan sila lain harus menunggu sila pertama sempurna dulu"],"a":0,"ex":"Menjiwai artinya nilai Ketuhanan menjadi ruh/landasan moral yang melandasi pengamalan kemanusiaan, persatuan, kerakyatan, dan keadilan."},
{"id":"TWK-3306","q":"Sikap yang mencerminkan pengamalan sila pertama Pancasila bagi seorang pelajar adalah ....","opts":["tidak menyontek saat ujian karena meyakini Tuhan Maha Melihat","beribadah hanya agar dipuji teman-temannya","mencontek dengan dalih yang penting nilai bagus","bolos sekolah untuk bermain gim daring","menyontek lalu berdoa agar tidak ketahuan guru"],"a":0,"ex":"Keyakinan bahwa Tuhan Maha Melihat mendorong kejujuran, misalnya menolak menyontek — itulah pengamalan sila pertama di sekolah."},
{"id":"TWK-3307","q":"Jaminan kebebasan beragama bagi warga negara Indonesia ditegaskan dalam UUD 1945 sebagai penjabaran sila pertama Pancasila, yaitu pada ....","opts":["Pasal 29 ayat (2)","Pasal 28 ayat (1)","Pasal 27 ayat (1)","Pasal 30 ayat (1)","Pasal 31 ayat (1)"],"a":0,"ex":"Pasal 29 ayat (2) UUD 1945 menjamin kemerdekaan tiap-tiap penduduk untuk memeluk agama dan beribadat menurut agamanya — penjabaran sila pertama."},
{"id":"TWK-3308","q":"Seorang ketua RT melarang warganya yang berbeda agama mengadakan ibadah di rumahnya. Tindakan tersebut bertentangan dengan sila Pancasila, yaitu ....","opts":["sila pertama","sila kedua","sila ketiga","sila keempat","sila kelima"],"a":0,"ex":"Melarang ibadah melanggar kebebasan beragama yang dijamin sila pertama, Ketuhanan Yang Maha Esa."},
{"id":"TWK-3309","q":"Dalam sila pertama Pancasila, kata 'Maha Esa' menegaskan bahwa ....","opts":["Tuhan itu satu dan menjadi sumber nilai tertinggi bangsa Indonesia","hanya ada satu agama yang diakui negara Indonesia","semua agama pada hakikatnya sama persis ajarannya","negara berhak mengatur tata cara ibadah setiap agama","warga negara tidak boleh menganut kepercayaan lokal"],"a":0,"ex":"'Maha Esa' menegaskan keesaan Tuhan sebagai sumber nilai tertinggi, tanpa menyeragamkan agama yang dianut warga."},
{"id":"TWK-3310","q":"Hubungan antara sila pertama Pancasila dan kehidupan bernegara di Indonesia ditunjukkan oleh ....","opts":["negara memfasilitasi kerukunan antarumat beragama melalui FKUB","negara menetapkan satu agama resmi yang wajib dipeluk","negara melarang seluruh kegiatan keagamaan di ruang publik","negara membiayai seluruh kegiatan ibadah warga negara","negara tidak mengurusi persoalan keagamaan sama sekali"],"a":0,"ex":"Melalui Forum Kerukunan Umat Beragama (FKUB), negara memfasilitasi kerukunan — wujud sila pertama dalam penyelenggaraan negara."},
{"id":"TWK-3311","q":"Nilai yang terkandung dalam sila pertama Pancasila apabila dikaitkan dengan ilmu pengetahuan adalah ....","opts":["pengembangan iptek harus dilandasi nilai-nilai ketuhanan dan moral","ilmu pengetahuan bertentangan dengan ajaran agama","penelitian ilmiah dilarang jika menyangkut soal ketuhanan","agama harus tunduk pada temuan ilmu pengetahuan","iptek dan agama tidak memiliki kaitan sama sekali"],"a":0,"ex":"Sila pertama menuntut iptek dikembangkan dengan landasan moral-ketuhanan agar tidak merusak kemanusiaan."},
{"id":"TWK-3312","q":"Pengamalan sila pertama Pancasila dalam lingkungan keluarga dapat diwujudkan dengan ....","opts":["orang tua memberi teladan beribadah dan menghargai keyakinan anggota keluarga","orang tua memaksa anak memeluk agama tertentu dengan ancaman","anggota keluarga dilarang membahas soal agama di rumah","anak dibebaskan tanpa bimbingan nilai agama sama sekali","keluarga hanya beribadah saat ada acara besar keagamaan"],"a":0,"ex":"Teladan beribadah dan sikap saling menghargai keyakinan di rumah adalah pengamalan sila pertama di tingkat keluarga."},
{"id":"TWK-3313","q":"Sila pertama Pancasila menjadi dasar bagi terwujudnya kerukunan umat beragama karena ....","opts":["mengajarkan bahwa perbedaan agama adalah rahmat yang harus dihormati","menuntut semua agama disatukan menjadi satu ajaran","membatasi jumlah agama yang boleh dianut warga negara","mewajibkan dialog antaragama setiap hari","menghapus perbedaan ajaran antaragama yang ada"],"a":0,"ex":"Sila pertama memandang perbedaan agama sebagai rahmat Tuhan yang wajib dihormati, itulah fondasi kerukunan."},
{"id":"TWK-3314","q":"Seorang pedagang berlaku jujur dalam takaran dagangannya karena meyakini Tuhan mengawasi setiap perbuatannya. Perilaku tersebut merupakan pengamalan Pancasila sila ....","opts":["pertama","kedua","ketiga","keempat","kelima"],"a":0,"ex":"Kejujuran yang didorong keyakinan akan pengawasan Tuhan adalah pengamalan sila pertama dalam kegiatan ekonomi."},
{"id":"TWK-3315","q":"Aksi intoleransi berupa perusakan rumah ibadah jelas bertentangan dengan Pancasila. Sila yang paling langsung dilanggar adalah ....","opts":["sila pertama","sila kedua","sila ketiga","sila keempat","sila kelima"],"a":0,"ex":"Perusakan rumah ibadah menyerang kebebasan beragama — pelanggaran langsung terhadap sila pertama."},
{"id":"TWK-3316","q":"Dalam konteks sila pertama Pancasila, toleransi beragama berarti ....","opts":["menghormati pelaksanaan ibadah agama lain tanpa mencampuradukkan akidah","ikut serta dalam ritual ibadah agama lain agar rukun","menganggap semua ajaran agama sama dan boleh dipertukarkan","tidak peduli terhadap kegiatan keagamaan orang lain","menyembunyikan identitas agama sendiri di ruang publik"],"a":0,"ex":"Toleransi = menghormati ibadah agama lain; bukan berarti ikut ritualnya atau mencampuradukkan akidah masing-masing."},
{"id":"TWK-3317","q":"Sila pertama Pancasila menolak paham ateisme sebagai pandangan hidup berbangsa karena ....","opts":["bangsa Indonesia mendasarkan kehidupan bernegaranya pada nilai Ketuhanan","ateisme dilarang oleh seluruh peraturan perundang-undangan","orang yang tidak beragama tidak diakui sebagai warga negara","paham ateisme terbukti merusak perekonomian nasional","negara hanya mengakui warga yang taat beribadah"],"a":0,"ex":"Sila pertama menegaskan bangsa Indonesia ber-Ketuhanan; ateisme sebagai ideologi bertentangan dengan dasar negara tersebut."},
{"id":"TWK-3318","q":"Contoh nyata pengamalan sila pertama Pancasila oleh aparatur negara adalah ....","opts":["pamong praja memfasilitasi dialog antar tokoh agama saat terjadi gesekan","lurah melarang pendirian rumah ibadah tanpa alasan jelas","camat memihak salah satu kelompok agama dalam sengketa","kepala desa membubarkan perayaan hari besar keagamaan","pejabat mempersulit izin kegiatan keagamaan minoritas"],"a":0,"ex":"Memfasilitasi dialog antar tokoh agama saat gesekan adalah peran aparatur dalam merawat kerukunan — pengamalan sila pertama."},
{"id":"TWK-3319","q":"Nilai ketuhanan dalam sila pertama Pancasila bersumber dari ....","opts":["keyakinan religius yang telah hidup dalam budaya bangsa Indonesia","keputusan politik para pendiri negara semata","pengaruh ideologi asing yang diadopsi mentah-mentah","hasil voting dalam sidang BPUPKI tahun 1945","tekanan golongan agama tertentu pada masa kemerdekaan"],"a":0,"ex":"Nilai ketuhanan digali dari budaya dan religiusitas bangsa Indonesia sendiri, bukan impor ideologi asing."},
{"id":"TWK-3320","q":"Sila pertama Pancasila menuntut keseimbangan antara ....","opts":["kewajiban beribadah kepada Tuhan dan penghormatan terhadap sesama manusia","kepentingan agama mayoritas dan penghapusan agama minoritas","kebebasan beragama dan kewajiban mengikuti tafsir negara","keyakinan pribadi dan penolakan terhadap perbedaan","ibadah ritual dan pengabaian tanggung jawab sosial"],"a":0,"ex":"Sila pertama menuntut keseimbangan vertikal (ibadah kepada Tuhan) dan horizontal (hormat kepada sesama)."},
{"id":"TWK-3321","q":"Seorang siswa menolak diajak tawuran dengan alasan agamanya melarang kekerasan. Sikap tersebut mencerminkan Pancasila sila ....","opts":["pertama","kedua","ketiga","keempat","kelima"],"a":0,"ex":"Menolak kekerasan karena larangan agama = nilai ketuhanan membimbing perilaku — pengamalan sila pertama."},
{"id":"TWK-3322","q":"Pancasila sila pertama memberikan landasan bahwa pembangunan nasional harus ....","opts":["memperhatikan nilai-nilai moral dan spiritual bangsa","mengabaikan aspirasi keagamaan masyarakat","dijalankan tanpa mempertimbangkan etika","fokus semata pada pertumbuhan ekonomi","meniru sepenuhnya model pembangunan negara sekuler"],"a":0,"ex":"Pembangunan nasional berlandaskan sila pertama wajib memperhatikan moral-spiritual, tidak semata material."},
{"id":"TWK-3323","q":"Bentuk pengamalan sila pertama Pancasila di era digital adalah ....","opts":["tidak menyebarkan ujaran kebencian bernuansa SARA di media sosial","menyebar hoaks tentang ritual agama tertentu agar viral","mengolok-olok keyakinan orang lain di kolom komentar","membuat meme yang menghina tokoh agama","mengajak pengikutnya memusuhi pemeluk agama lain"],"a":0,"ex":"Menahan diri dari ujaran kebencian SARA di medsos adalah pengamalan sila pertama di ruang digital."},
{"id":"TWK-3324","q":"Sila pertama Pancasila berkaitan erat dengan sila kedua karena ....","opts":["pengakuan terhadap Tuhan diwujudkan melalui penghormatan terhadap kemanusiaan","sila pertama dan kedua memiliki bunyi yang sama","keduanya mengatur tentang tata cara beribadah","sila kedua merupakan pengganti sila pertama","pengamalan keduanya hanya berlaku bagi tokoh agama"],"a":0,"ex":"Ketuhanan (sila 1) menjiwai kemanusiaan (sila 2): iman kepada Tuhan diwujudkan lewat memanusiakan manusia."},
{"id":"TWK-3325","q":"Hari Kesaktian Pancasila yang diperingati setiap 1 Oktober berkaitan dengan sila pertama karena ....","opts":["peristiwa G30S/PKI merupakan pengkhianatan terhadap nilai Ketuhanan dan Pancasila","pada tanggal itu sila pertama Pancasila disahkan","tokoh agama memimpin upacara peringatan tersebut","seluruh rumah ibadah mengadakan doa bersama","pemerintah menetapkan hari libur keagamaan nasional"],"a":0,"ex":"G30S/PKI 1965 dipandang sebagai pengkhianatan terhadap Pancasila termasuk nilai Ketuhanan — diperingati sebagai Hari Kesaktian Pancasila tiap 1 Oktober."},
{"id":"TWK-3326","q":"Bunyi sila kedua Pancasila adalah ....","opts":["Kemanusiaan yang adil dan beradab","Ketuhanan Yang Maha Esa","Persatuan Indonesia","Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan","Keadilan sosial bagi seluruh rakyat Indonesia"],"a":0,"ex":"Sila kedua berbunyi 'Kemanusiaan yang adil dan beradab', menegaskan harkat dan martabat setiap manusia."},
{"id":"TWK-3327","q":"Makna 'adil dan beradab' dalam sila kedua Pancasila adalah ....","opts":["manusia diperlakukan sesuai haknya dengan menjunjung tinggi nilai moral dan budaya","manusia bebas berbuat apa saja tanpa aturan","keadilan hanya berlaku bagi warga negara yang taat hukum","adab hanya wajib ditunjukkan kepada pejabat negara","keadilan berarti semua orang menerima bagian yang sama persis"],"a":0,"ex":"'Adil' = sesuai hak dan kewajiban; 'beradab' = menjunjung moral, budaya, dan martabat kemanusiaan."},
{"id":"TWK-3328","q":"Contoh pengamalan sila kedua Pancasila di sekolah adalah ....","opts":["menolong teman yang kesulitan memahami pelajaran tanpa pamrih","menertawakan teman yang mendapat nilai jelek","memalak uang jajan adik kelas setiap hari","mengucilkan teman yang berbeda suku","menyontek jawaban teman saat ulangan"],"a":0,"ex":"Menolong teman tanpa pamrih adalah wujud memanusiakan manusia — inti sila kedua."},
{"id":"TWK-3329","q":"Tindakan yang mencerminkan pelanggaran terhadap sila kedua Pancasila adalah ....","opts":["melakukan perundungan (bullying) terhadap teman yang lemah","menggalang dana untuk korban bencana alam","menjadi relawan donor darah secara rutin","membantu lansia menyeberang jalan","menghormati guru dan orang tua"],"a":0,"ex":"Perundungan merendahkan martabat manusia — pelanggaran nyata terhadap sila kedua."},
{"id":"TWK-3330","q":"Sila kedua Pancasila menjadi dasar Indonesia menolak segala bentuk penjajahan karena ....","opts":["penjajahan merampas kemerdekaan dan martabat kemanusiaan suatu bangsa","penjajahan merugikan perekonomian negara penjajah","bangsa Indonesia pernah menjadi negara penjajah","penjajahan hanya merugikan sektor pariwisata","penjajahan tidak ada kaitannya dengan nilai kemanusiaan"],"a":0,"ex":"Penjajahan menindas kemanusiaan; sila kedua menuntut setiap bangsa merdeka dan bermartabat — sejalan dengan Pembukaan UUD 1945."},
{"id":"TWK-3331","q":"Dalam sila kedua Pancasila, pengakuan terhadap persamaan derajat manusia berarti ....","opts":["setiap orang berhak diperlakukan sama di depan hukum tanpa diskriminasi","semua orang harus memiliki harta yang sama banyak","tidak ada perbedaan peran antara laki-laki dan perempuan","semua warga negara wajib memiliki pekerjaan yang sama","perbedaan pendapat tidak boleh ada dalam masyarakat"],"a":0,"ex":"Persamaan derajat = persamaan di depan hukum dan hak asasi, bukan penyeragaman harta atau peran."},
{"id":"TWK-3332","q":"Seorang dokter melayani pasien miskin dan kaya dengan standar yang sama. Sikap tersebut mengamalkan Pancasila sila ....","opts":["kedua","pertama","ketiga","keempat","kelima"],"a":0,"ex":"Melayani tanpa membedakan status sosial adalah penghormatan pada martabat kemanusiaan — sila kedua."},
{"id":"TWK-3333","q":"Sila kedua Pancasila menjiwai penegakan hukum di Indonesia dengan prinsip ....","opts":["hukum ditegakkan secara adil dan manusiawi tanpa pandang bulu","hukum hanya tajam kepada rakyat kecil","pelanggar hukum boleh diperlakukan semena-mena","keadilan dapat dibeli dengan kekuasaan","hukum tidak perlu memperhatikan hak asasi tersangka"],"a":0,"ex":"Sila kedua menuntut penegakan hukum yang adil sekaligus manusiawi, menghormati HAM setiap orang termasuk tersangka."},
{"id":"TWK-3334","q":"Contoh pengamalan sila kedua Pancasila dalam kehidupan bermasyarakat adalah ....","opts":["warga bergotong royong membangun jembatan desa yang rusak","warga menolak membantu tetangga yang tertimpa musibah","pemuda tawuran antar kampung setiap malam minggu","warga membiarkan pengemis kelaparan di depan rumahnya","tetangga saling memfitnah demi memenangkan pemilihan RT"],"a":0,"ex":"Gotong royong membangun fasilitas umum adalah wujud kepedulian kemanusiaan dalam masyarakat."},
{"id":"TWK-3335","q":"Perdagangan manusia (human trafficking) bertentangan dengan Pancasila terutama sila ....","opts":["kedua","pertama","ketiga","keempat","kelima"],"a":0,"ex":"Human trafficking menjadikan manusia sebagai barang dagangan — penghinaan terhadap martabat kemanusiaan (sila kedua)."},
{"id":"TWK-3336","q":"Nilai kemanusiaan dalam sila kedua Pancasila bersifat universal, artinya ....","opts":["berlaku bagi seluruh umat manusia tanpa memandang bangsa dan agama","hanya berlaku bagi warga negara Indonesia","hanya berlaku dalam hubungan antar pejabat negara","tidak berlaku dalam hubungan internasional","berlaku hanya pada masa perang saja"],"a":0,"ex":"Kemanusiaan adalah nilai universal; sila kedua berlaku bagi semua manusia, melampaui batas bangsa dan agama."},
{"id":"TWK-3337","q":"Sikap beradab dalam sila kedua Pancasila ditunjukkan dengan ....","opts":["bertutur kata sopan dan menghargai orang lain dalam pergaulan","berbicara kasar agar ditakuti lawan bicara","memotong pembicaraan orang yang lebih tua","menyela antrean demi kepentingan sendiri","mengejek kekurangan fisik orang lain"],"a":0,"ex":"Beradab = menjunjung sopan santun dan menghargai sesama dalam pergaulan sehari-hari."},
{"id":"TWK-3338","q":"Seorang majikan memberikan upah layak dan cuti kepada asisten rumah tangganya. Perbuatan itu mencerminkan sila Pancasila, yaitu ....","opts":["sila kedua","sila pertama","sila ketiga","sila keempat","sila kelima"],"a":0,"ex":"Memperlakukan pekerja secara manusiawi dengan upah layak adalah pengamalan sila kedua di bidang ketenagakerjaan."},
{"id":"TWK-3339","q":"Diskriminasi ras dalam penerimaan karyawan bertentangan dengan sila kedua Pancasila karena ....","opts":["setiap manusia memiliki martabat dan hak yang sama","perusahaan berhak memilih karyawan sesukanya","diskriminasi meningkatkan efisiensi perusahaan","ras tertentu memang lebih unggul dari ras lain","persamaan hak hanya berlaku di sektor pemerintahan"],"a":0,"ex":"Sila kedua menjunjung persamaan martabat; diskriminasi ras merendahkan kemanusiaan seseorang."},
{"id":"TWK-3340","q":"Pengamalan sila kedua Pancasila oleh generasi muda di era digital dapat diwujudkan dengan ....","opts":["tidak menyebarkan konten perundungan siber terhadap siapa pun","ikut menyebarkan aib teman di media sosial","membuat akun anonim untuk menghina orang lain","menyebarluaskan data pribadi orang tanpa izin","mengancam teman melalui pesan daring agar dituruti"],"a":0,"ex":"Menolak cyberbullying dan menjaga martabat orang lain di dunia maya adalah sila kedua era digital."},
{"id":"TWK-3341","q":"Sila kedua Pancasila menjadi landasan moral bagi Indonesia dalam memberikan suaka kepada pengungsi karena ....","opts":["pengungsi adalah manusia yang martabat dan keselamatannya wajib dilindungi","pengungsi dapat dimanfaatkan sebagai tenaga kerja murah","pemberian suaka meningkatkan citra politik pemerintah","pengungsi wajib mengganti biaya penampungan","suaka hanya diberikan kepada pengungsi yang seagama"],"a":0,"ex":"Nilai kemanusiaan universal mewajibkan perlindungan terhadap pengungsi sebagai sesama manusia."},
{"id":"TWK-3342","q":"Hubungan sila kedua dengan sila pertama Pancasila adalah ....","opts":["keyakinan kepada Tuhan diwujudkan dalam sikap memanusiakan sesama manusia","sila kedua lebih tinggi kedudukannya daripada sila pertama","keduanya tidak memiliki keterkaitan sama sekali","sila pertama hanya untuk urusan ibadah ritual","sila kedua meniadakan peran nilai ketuhanan"],"a":0,"ex":"Sila pertama menjiwai sila kedua: iman kepada Tuhan dibuktikan dengan memanusiakan manusia."},
{"id":"TWK-3343","q":"Seorang siswa membela temannya yang dirundung kakak kelas meski berisiko ikut dimusuhi. Tindakan tersebut mengamalkan Pancasila sila ....","opts":["kedua","pertama","ketiga","keempat","kelima"],"a":0,"ex":"Membela korban perundungan adalah keberpihakan pada martabat kemanusiaan — sila kedua."},
{"id":"TWK-3344","q":"Prinsip 'adil' dalam sila kedua Pancasila apabila diterapkan dalam pembagian tugas kelompok berarti ....","opts":["tugas dibagi sesuai kemampuan dan kebutuhan anggota secara proporsional","semua anggota mengerjakan bagian yang sama persis","ketua kelompok mengerjakan seluruh tugas sendirian","anggota yang pintar dibebaskan dari tugas","tugas diberikan hanya kepada anggota yang disukai"],"a":0,"ex":"Adil = proporsional sesuai kemampuan, bukan sama rata secara matematis."},
{"id":"TWK-3345","q":"Pelanggaran HAM berat seperti pembunuhan massal bertentangan dengan Pancasila karena ....","opts":["menghilangkan hak hidup yang merupakan hak asasi paling mendasar","pelakunya selalu berasal dari kelompok tertentu","korbannya tidak melawan saat diserang","peristiwanya terjadi di masa lampau","tidak ada kaitannya dengan nilai Pancasila"],"a":0,"ex":"Hak hidup adalah HAM paling mendasar; pembunuhan massal adalah pelanggaran berat sila kedua."},
{"id":"TWK-3346","q":"Wujud pengamalan sila kedua Pancasila dalam dunia kesehatan adalah ....","opts":["tenaga medis memberikan pertolongan pertama kepada siapa pun tanpa diskriminasi","rumah sakit menolak pasien yang tidak mampu membayar","dokter memilih pasien berdasarkan status sosialnya","perawat mengabaikan pasien dari daerah terpencil","puskesmas melayani hanya warga yang membawa KTP setempat"],"a":0,"ex":"Pertolongan medis tanpa diskriminasi adalah penghormatan tertinggi pada nilai kemanusiaan."},
{"id":"TWK-3347","q":"Sila kedua Pancasila menolak perbudakan modern dalam bentuk apa pun karena ....","opts":["manusia bukan komoditas yang dapat diperjualbelikan","perbudakan merugikan perekonomian negara","budak tidak mampu bekerja secara maksimal","perbudakan hanya terjadi di negara maju","penghapusan perbudakan mengurangi lapangan kerja"],"a":0,"ex":"Manusia bermartabat, bukan barang; segala bentuk perbudakan modern menodai sila kedua."},
{"id":"TWK-3348","q":"Sikap tenggang rasa terhadap tetangga yang sedang berduka merupakan pengamalan Pancasila sila ....","opts":["kedua","pertama","ketiga","keempat","kelima"],"a":0,"ex":"Tenggang rasa dan empati terhadap duka sesama adalah wujud kemanusiaan yang beradab."},
{"id":"TWK-3349","q":"Dalam sila kedua Pancasila, kata 'beradab' mengandung pengertian bahwa bangsa Indonesia ....","opts":["menjunjung tinggi nilai moral, sopan santun, dan budaya luhur","telah mencapai kemajuan teknologi tertinggi","wajib mengikuti seluruh budaya asing yang masuk","meninggalkan seluruh tradisi nenek moyang","mengutamakan kepentingan individu di atas segalanya"],"a":0,"ex":"'Beradab' = berbudaya luhur: moral, sopan santun, dan tata krama dalam kehidupan bersama."},
{"id":"TWK-3350","q":"Seorang pengusaha membangun sekolah gratis bagi anak-anak kurang mampu di sekitar pabriknya. Tindakan tersebut selaras dengan Pancasila sila ....","opts":["kedua","pertama","ketiga","keempat","kelima"],"a":0,"ex":"Kepedulian pada pendidikan kaum lemah adalah wujud nyata memanusiakan manusia — sila kedua."},
{"id":"TWK-3351","q":"Bunyi sila ketiga Pancasila adalah ....","opts":["Persatuan Indonesia","Ketuhanan Yang Maha Esa","Kemanusiaan yang adil dan beradab","Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan","Keadilan sosial bagi seluruh rakyat Indonesia"],"a":0,"ex":"Sila ketiga berbunyi 'Persatuan Indonesia', menegaskan tekad bangsa untuk bersatu dalam NKRI."},
{"id":"TWK-3352","q":"Makna sila ketiga Pancasila bagi bangsa Indonesia adalah ....","opts":["menempatkan persatuan dan kesatuan bangsa di atas kepentingan pribadi atau golongan","setiap daerah boleh memisahkan diri jika tidak puas","kepentingan golongan lebih utama daripada bangsa","persatuan hanya diperlukan saat ada perang","perbedaan suku dan agama harus dihapuskan"],"a":0,"ex":"Sila ketiga menuntut persatuan di atas kepentingan pribadi/golongan, sambil tetap menghargai kebinekaan."},
{"id":"TWK-3353","q":"Seorang warga dengan sukarela melestarikan kesenian daerahnya dan mengenalkannya kepada wisatawan. Perbuatan tersebut adalah wujud nyata sila Pancasila, yaitu ....","opts":["ketiga","pertama","kedua","keempat","kelima"],"a":0,"ex":"Melestarikan dan mempromosikan budaya daerah adalah bentuk nasionalisme dan cinta persatuan Indonesia — sila ketiga."},
{"id":"TWK-3354","q":"Perilaku yang bertentangan dengan sila ketiga Pancasila adalah ....","opts":["melakukan tawuran antar pelajar yang merusak persatuan","ikut serta dalam upacara bendera dengan khidmat","mempelajari tarian tradisional daerah lain","menggunakan bahasa Indonesia yang baik dan benar","menolong korban bencana tanpa memandang asal daerah"],"a":0,"ex":"Tawuran merusak persatuan dan persaudaraan — pelanggaran nyata sila ketiga."},
{"id":"TWK-3355","q":"Sila ketiga Pancasila menjadi landasan bagi semboyan Bhinneka Tunggal Ika karena ....","opts":["keduanya menegaskan persatuan dalam keberagaman bangsa Indonesia","Bhinneka Tunggal Ika hanya berlaku bagi suku Jawa","sila ketiga menghapus seluruh perbedaan di Indonesia","semboyan itu tidak ada kaitannya dengan Pancasila","keberagaman dianggap sebagai penghambat persatuan"],"a":0,"ex":"Sila ketiga dan Bhinneka Tunggal Ika sama-sama menegaskan: berbeda-beda tetapi tetap satu."},
{"id":"TWK-3356","q":"Sikap yang mencerminkan sila ketiga Pancasila bagi seorang pelajar adalah ....","opts":["berteman dengan siapa saja tanpa membedakan suku dan agama","hanya mau bergaul dengan teman satu suku","mengejek logat daerah teman dari luar pulau","menolak mengikuti kegiatan kebudayaan sekolah","membentuk geng berdasarkan kesukuan"],"a":0,"ex":"Bergaul lintas suku dan agama tanpa diskriminasi adalah pengamalan sila ketiga di sekolah."},
{"id":"TWK-3357","q":"Gerakan separatisme yang ingin memisahkan diri dari NKRI bertentangan dengan Pancasila sila ....","opts":["ketiga","pertama","kedua","keempat","kelima"],"a":0,"ex":"Separatisme merongrong persatuan Indonesia — pelanggaran langsung sila ketiga."},
{"id":"TWK-3358","q":"Dalam sila ketiga Pancasila, nasionalisme yang benar berarti ....","opts":["mencintai bangsa dan negara tanpa merendahkan bangsa lain","membenci segala hal yang berasal dari luar negeri","menganggap bangsa sendiri paling unggul di dunia","menutup diri dari pergaulan internasional","memaksakan budaya sendiri kepada suku lain"],"a":0,"ex":"Nasionalisme Pancasila = cinta tanah air yang tidak chauvinistik dan tetap menghormati bangsa lain."},
{"id":"TWK-3359","q":"Contoh pengamalan sila ketiga Pancasila di lingkungan tempat tinggal adalah ....","opts":["warga berbeda suku bahu-membahu dalam kerja bakti membersihkan lingkungan","warga menolak tetangga baru karena berbeda daerah asal","pemuda mengadakan tawuran antar RT setiap bulan","warga saling bermusuhan karena beda pilihan politik","ketua RT hanya memperhatikan warganya yang satu suku"],"a":0,"ex":"Kerja bakti lintas suku adalah gotong royong — wujud persatuan di tingkat lingkungan."},
{"id":"TWK-3360","q":"Sila ketiga Pancasila menuntut warga negara untuk rela berkorban demi ....","opts":["kepentingan bangsa dan negara di atas kepentingan pribadi","kepentingan keluarganya semata","memperkaya diri sendiri","kejayaan golongan politiknya","kepentingan negara asing yang berjasa"],"a":0,"ex":"Rela berkorban untuk bangsa dan negara adalah inti pengamalan sila ketiga."},
{"id":"TWK-3361","q":"Penggunaan bahasa Indonesia sebagai bahasa persatuan merupakan pengamalan sila ketiga Pancasila karena ....","opts":["bahasa Indonesia menjadi alat pemersatu seluruh suku bangsa","bahasa daerah harus dihapuskan dari kehidupan","hanya bahasa Indonesia yang boleh dipelajari","bahasa asing dilarang digunakan di Indonesia","bahasa Indonesia lebih unggul dari bahasa daerah"],"a":0,"ex":"Bahasa Indonesia sebagai bahasa persatuan (Sumpah Pemuda 1928) adalah instrumen persatuan — bukan untuk menghapus bahasa daerah."},
{"id":"TWK-3362","q":"Seorang atlet Indonesia menangis haru saat lagu Indonesia Raya berkumandang di podium juara. Perasaan tersebut berkaitan dengan Pancasila sila ....","opts":["ketiga","pertama","kedua","keempat","kelima"],"a":0,"ex":"Kebanggaan dan haru mengharumkan nama bangsa adalah ekspresi nasionalisme — sila ketiga."},
{"id":"TWK-3363","q":"Tindakan provokasi bernuansa SARA di media sosial bertentangan dengan sila ketiga Pancasila karena ....","opts":["dapat memecah belah persatuan dan kesatuan bangsa","membuat pengguna media sosial semakin terkenal","kritik terhadap pemerintah dilarang total","kebebasan berpendapat tidak dijamin konstitusi","media sosial hanya untuk hiburan semata"],"a":0,"ex":"Provokasi SARA mengancam persatuan — pelanggaran sila ketiga di ruang digital."},
{"id":"TWK-3364","q":"Sila ketiga Pancasila diwujudkan dalam bidang pertahanan negara melalui ....","opts":["sistem pertahanan keamanan rakyat semesta yang melibatkan seluruh warga","pertahanan yang hanya menjadi urusan TNI semata","penyerahan keamanan kepada negara asing","pembubaran seluruh komponen pertahanan rakyat","pertahanan yang mengandalkan senjata nuklir"],"a":0,"ex":"Sishankamrata melibatkan seluruh warga dan sumber daya nasional — perwujudan persatuan dalam pertahanan."},
{"id":"TWK-3365","q":"Sikap cinta tanah air sebagai pengamalan sila ketiga Pancasila dapat ditunjukkan dengan ....","opts":["membayar pajak tepat waktu untuk pembangunan negara","menghindari kewajiban pajak dengan berbagai cara","menyelundupkan barang impor ilegal","merusak fasilitas umum saat demonstrasi","menyebarluaskan rahasia negara ke pihak asing"],"a":0,"ex":"Membayar pajak adalah kontribusi nyata warga bagi pembangunan bangsa — wujud cinta tanah air."},
{"id":"TWK-3366","q":"Keberagaman suku, agama, dan budaya di Indonesia menurut sila ketiga Pancasila harus ....","opts":["dijadikan kekuatan pemersatu bangsa, bukan sumber perpecahan","diseragamkan agar tidak menimbulkan perbedaan","dianggap sebagai kelemahan bangsa Indonesia","dibiarkan tanpa ada upaya merawatnya","dijadikan alasan untuk saling bermusuhan"],"a":0,"ex":"Sila ketiga memandang kebinekaan sebagai kekayaan pemersatu, bukan ancaman."},
{"id":"TWK-3367","q":"Seorang kepala daerah membuat kebijakan yang hanya menguntungkan sukunya sendiri. Kebijakan tersebut bertentangan dengan Pancasila sila ....","opts":["ketiga","pertama","kedua","keempat","kelima"],"a":0,"ex":"Nepotisme kesukuan mengkhianati persatuan Indonesia — pelanggaran sila ketiga."},
{"id":"TWK-3368","q":"Hubungan sila ketiga dengan sila pertama Pancasila adalah ....","opts":["persatuan bangsa dilandasi nilai Ketuhanan yang mengajarkan kasih sayang","keduanya saling bertentangan dan tidak bisa didamaikan","sila ketiga menghapus peran nilai ketuhanan","persatuan hanya bisa dicapai tanpa nilai agama","sila pertama tidak relevan bagi persatuan bangsa"],"a":0,"ex":"Nilai Ketuhanan menjiwai persatuan: kasih sayang antar sesama menjadi perekat kebinekaan."},
{"id":"TWK-3369","q":"Pengamalan sila ketiga Pancasila dalam kegiatan ekonomi ditunjukkan dengan ....","opts":["mengutamakan kerja sama antar daerah untuk pemerataan pembangunan","menimbun kebutuhan pokok demi keuntungan pribadi","melakukan persaingan usaha dengan cara curang","menolak produk dari daerah lain","memboikot usaha milik suku tertentu"],"a":0,"ex":"Kerja sama antar daerah demi pemerataan adalah persatuan di bidang ekonomi."},
{"id":"TWK-3370","q":"Sumpah Pemuda 28 Oktober 1928 merupakan tonggak sejarah yang sejiwa dengan sila ketiga Pancasila karena ....","opts":["menegaskan tekad satu tanah air, satu bangsa, dan satu bahasa","hanya diikuti oleh pemuda dari Pulau Jawa","menuntut kemerdekaan Indonesia saat itu juga","menolak penggunaan bahasa Indonesia","memecah pemuda berdasarkan kedaerahan"],"a":0,"ex":"Ikrar satu tanah air, satu bangsa, satu bahasa Indonesia adalah manifestasi persatuan — sejiwa sila ketiga."},
{"id":"TWK-3371","q":"Sikap yang harus dikembangkan untuk mengamalkan sila ketiga Pancasila di tengah perbedaan pilihan politik adalah ....","opts":["tetap menghormati perbedaan dan menjaga persaudaraan sebangsa","memutus hubungan dengan pendukung calon yang berbeda","menyebarkan fitnah terhadap lawan politik","melakukan kekerasan terhadap kelompok berbeda pilihan","menganggap musuh politik sebagai musuh bangsa"],"a":0,"ex":"Beda pilihan politik tidak boleh merusak persaudaraan sebangsa — itulah sila ketiga."},
{"id":"TWK-3372","q":"Bentuk nyata bela negara sebagai pengamalan sila ketiga Pancasila bagi warga sipil adalah ....","opts":["menjaga kerukunan dan tidak mudah terprovokasi isu pemecah belah","wajib mengikuti latihan militer setiap akhir pekan","menolak membayar pajak untuk negara","menyimpan senjata api di rumah masing-masing","bergabung dengan kelompok bersenjata liar"],"a":0,"ex":"Bagi warga sipil, bela negara berwujud menjaga kerukunan dan ketahanan sosial — bukan angkat senjata."},
{"id":"TWK-3373","q":"Sila ketiga Pancasila menolak paham etnosentrisme karena ....","opts":["etnosentrisme menganggap suku sendiri paling unggul dan merendahkan suku lain","etnosentrisme justru memperkuat persatuan nasional","suku bangsa Indonesia tidak memiliki kebudayaan","perbedaan suku harus dipertajam agar jelas","etnosentrisme dianjurkan dalam Pancasila"],"a":0,"ex":"Etnosentrisme merendahkan suku lain — berlawanan dengan persatuan dalam kebinekaan."},
{"id":"TWK-3374","q":"Seorang guru mengajak murid-muridnya menghafal lagu-lagu daerah dari berbagai provinsi. Kegiatan tersebut mengamalkan Pancasila sila ....","opts":["ketiga","pertama","kedua","keempat","kelima"],"a":0,"ex":"Menghargai dan melestarikan budaya daerah lain adalah wujud cinta persatuan Indonesia."},
{"id":"TWK-3375","q":"Dalam sila ketiga Pancasila, persatuan Indonesia dimaknai sebagai persatuan yang ....","opts":["bersifat dinamis, terus dipupuk melalui kesadaran berbangsa","sudah final dan tidak perlu dirawat lagi","hanya diwujudkan lewat upacara bendera","berarti penyeragaman seluruh aspek kehidupan","tercapai dengan sendirinya tanpa usaha"],"a":0,"ex":"Persatuan bersifat dinamis — harus terus dipupuk lewat kesadaran dan tindakan nyata berbangsa."},
{"id":"TWK-3376","q":"Bunyi sila keempat Pancasila adalah ....","opts":["Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan","Ketuhanan Yang Maha Esa","Kemanusiaan yang adil dan beradab","Persatuan Indonesia","Keadilan sosial bagi seluruh rakyat Indonesia"],"a":0,"ex":"Sila keempat berbunyi 'Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan'."},
{"id":"TWK-3377","q":"Frasa 'dipimpin oleh hikmat kebijaksanaan' pada sila keempat Pancasila menegaskan bahwa proses musyawarah harus ....","opts":["dilandasi nalar sehat, pertimbangan jernih, serta nilai luhur kemanusiaan","dipimpin oleh orang yang paling tua usianya","menghasilkan keputusan dalam waktu sesingkat mungkin","didominasi oleh peserta yang paling pandai berbicara","mengikuti seluruh keinginan pimpinan rapat"],"a":0,"ex":"'Dipimpin hikmat kebijaksanaan' = musyawarah berjalan dengan nalar sehat dan nilai luhur, bukan dominasi usia, kepandaian bicara, atau kecepatan."},
{"id":"TWK-3378","q":"Contoh pengamalan sila keempat Pancasila di lingkungan sekolah adalah ....","opts":["pemilihan ketua OSIS dilakukan melalui musyawarah dan pemungutan suara yang jujur","ketua OSIS ditunjuk langsung oleh kepala sekolah tanpa musyawarah","siswa dipaksa menerima keputusan yang merugikan mereka","pemilihan ketua kelas dimenangkan dengan politik uang","suara siswa minoritas diabaikan dalam setiap rapat"],"a":0,"ex":"Pemilihan melalui musyawarah dan voting jujur adalah demokrasi Pancasila di sekolah."},
{"id":"TWK-3379","q":"Perilaku yang bertentangan dengan sila keempat Pancasila adalah ....","opts":["memaksakan kehendak dengan kekerasan dalam rapat warga","menghargai pendapat peserta musyawarah yang berbeda","menerima hasil musyawarah dengan lapang dada","memberi kesempatan setiap warga menyampaikan usulan","melaksanakan keputusan musyawarah dengan tanggung jawab"],"a":0,"ex":"Memaksakan kehendak dengan kekerasan meniadakan musyawarah — pelanggaran sila keempat."},
{"id":"TWK-3380","q":"Prinsip musyawarah dalam sila keempat Pancasila mengandung arti ....","opts":["setiap persoalan dibahas bersama untuk mencapai mufakat","segala keputusan ditentukan oleh suara terbanyak semata","musyawarah hanya formalitas untuk mengesahkan keputusan pimpinan","perbedaan pendapat harus dihilangkan dengan paksaan","musyawarah boleh mengorbankan kelompok minoritas"],"a":0,"ex":"Musyawarah = pembahasan bersama menuju mufakat; voting hanya jalan terakhir bila mufakat tak tercapai."},
{"id":"TWK-3381","q":"Sila keempat Pancasila menjadi dasar sistem demokrasi di Indonesia yang disebut ....","opts":["demokrasi Pancasila","demokrasi liberal","demokrasi terpimpin ala orde lama","demokrasi parlementer murni","demokrasi tanpa perwakilan"],"a":0,"ex":"Indonesia menganut demokrasi Pancasila: kerakyatan yang dipimpin hikmat kebijaksanaan dalam permusyawaratan/perwakilan."},
{"id":"TWK-3382","q":"Dalam sila keempat Pancasila, kedudukan wakil rakyat (DPR) adalah ....","opts":["menyampaikan aspirasi rakyat dan bermusyawarah dalam mengambil keputusan","berkuasa mutlak tanpa perlu mendengar rakyat","hanya menjadi stempel keputusan pemerintah","tidak memiliki tanggung jawab kepada konstituennya","boleh mengabaikan hasil musyawarah dengan rakyat"],"a":0,"ex":"Wakil rakyat adalah perpanjangan kerakyatan: menyerap aspirasi dan bermusyawarah — bukan penguasa mutlak."},
{"id":"TWK-3383","q":"Seorang ketua RT mengambil keputusan sepihak tanpa mengajak warga bermusyawarah. Tindakan tersebut melanggar Pancasila sila ....","opts":["keempat","pertama","kedua","ketiga","kelima"],"a":0,"ex":"Keputusan sepihak meniadakan musyawarah — pelanggaran sila keempat."},
{"id":"TWK-3384","q":"Nilai yang terkandung dalam sila keempat Pancasila apabila dikaitkan dengan pemilihan umum adalah ....","opts":["pemilu dilaksanakan secara langsung, umum, bebas, rahasia, jujur, dan adil","pemilu hanya diikuti oleh golongan tertentu","hasil pemilu boleh dimanipulasi oleh penyelenggara","rakyat tidak perlu ikut serta dalam pemilu","pemenang pemilu berhak bertindak sewenang-wenang"],"a":0,"ex":"Sila keempat menuntut pemilu luber jurdil sebagai wujud kedaulatan rakyat."},
{"id":"TWK-3385","q":"Musyawarah untuk mencapai mufakat sebagai cerminan sila keempat Pancasila telah dipraktikkan bangsa Indonesia sejak ....","opts":["zaman kerajaan melalui lembaga musyawarah adat dan dewan penasihat raja","masa penjajahan Belanda melalui volksraad semata","kemerdekaan Indonesia tahun 1945","berlakunya UUD 1945 hasil amandemen","diterapkannya otonomi daerah tahun 1999"],"a":0,"ex":"Tradisi musyawarah sudah hidup sejak zaman kerajaan (mis. dewan penasihat raja, musyawarah adat) — akar budaya sila keempat."},
{"id":"TWK-3386","q":"Sikap yang harus ditunjukkan peserta musyawarah sesuai sila keempat Pancasila adalah ....","opts":["berani menyampaikan pendapat dan menghormati pendapat orang lain","diam saja dan menerima apa pun keputusannya","memaksakan pendapatnya agar selalu menang","meninggalkan musyawarah sebelum selesai","mengejek peserta yang pendapatnya berbeda"],"a":0,"ex":"Musyawarah sehat = berani berpendapat + menghormati pendapat lain."},
{"id":"TWK-3387","q":"Apabila musyawarah tidak mencapai mufakat, langkah yang sesuai sila keempat Pancasila adalah ....","opts":["mengambil keputusan melalui pemungutan suara dengan tetap menghormati suara minoritas","membubarkan musyawarah dan melupakan persoalannya","menyerahkan keputusan sepenuhnya kepada pihak asing","memaksakan pendapat kelompok mayoritas tanpa batas","menunda persoalan sampai semua pihak lupa"],"a":0,"ex":"Voting adalah jalan terakhir bila mufakat gagal; suara minoritas tetap dihormati — itulah demokrasi Pancasila."},
{"id":"TWK-3388","q":"Sila keempat Pancasila menolak sistem pemerintahan otoriter karena ....","opts":["kedaulatan berada di tangan rakyat yang dilaksanakan melalui permusyawaratan","rakyat tidak mampu memimpin dirinya sendiri","pemimpin otoriter selalu lebih sejahtera","musyawarah hanya menghambat pembangunan","rakyat harus selalu patuh tanpa bertanya"],"a":0,"ex":"Sila keempat menegaskan kedaulatan rakyat; otoritarianisme meniadakan peran rakyat dalam pengambilan keputusan."},
{"id":"TWK-3389","q":"Contoh pengamalan sila keempat Pancasila dalam keluarga adalah ....","opts":["orang tua dan anak bermusyawarah menentukan tujuan liburan keluarga","ayah memutuskan semuanya tanpa mendengar pendapat anggota keluarga","anak memaksakan kehendaknya dengan mengancam mogok makan","ibu tidak pernah dilibatkan dalam keputusan keluarga","keputusan keluarga selalu ditentukan oleh anak tertua"],"a":0,"ex":"Musyawarah keluarga dalam hal sederhana seperti liburan adalah pengamalan sila keempat di rumah."},
{"id":"TWK-3390","q":"Hubungan sila keempat dengan sila ketiga Pancasila adalah ....","opts":["musyawarah menjadi sarana menjaga dan memperkokoh persatuan Indonesia","keduanya saling bertentangan dalam praktiknya","sila keempat menghapus makna persatuan","persatuan hanya dicapai tanpa musyawarah","musyawarah justru memecah belah persatuan"],"a":0,"ex":"Musyawarah (sila 4) adalah instrumen merawat persatuan (sila 3): perbedaan diselesaikan lewat dialog, bukan kekerasan."},
{"id":"TWK-3391","q":"Dalam sila keempat Pancasila, makna 'perwakilan' adalah ....","opts":["rakyat melaksanakan kedaulatannya melalui wakil yang dipilih dalam pemilu","rakyat tidak perlu terlibat dalam kehidupan bernegara","wakil rakyat bebas bertindak tanpa mempertanggungjawabkan","perwakilan hanya berlaku di tingkat pusat","kedaulatan rakyat dialihkan sepenuhnya kepada presiden"],"a":0,"ex":"'Perwakilan' = kedaulatan rakyat dijalankan lewat wakil-wakil yang dipilih secara demokratis."},
{"id":"TWK-3392","q":"Seorang lurah mengadakan rembug warga sebelum menetapkan program pembangunan. Tindakan tersebut mencerminkan Pancasila sila ....","opts":["keempat","pertama","kedua","ketiga","kelima"],"a":0,"ex":"Rembug warga sebelum menetapkan program = musyawarah — pengamalan sila keempat di tingkat kelurahan."},
{"id":"TWK-3393","q":"Tantangan pengamalan sila keempat Pancasila di era media sosial adalah ....","opts":["maraknya ujaran kebencian yang merusak etika berdialog dan bermusyawarah","media sosial mempermudah musyawarah warga","semua orang menjadi lebih bijak berpendapat","hoaks tidak lagi beredar di masyarakat","perbedaan pendapat sudah tidak ada lagi"],"a":0,"ex":"Ujaran kebencian dan hoaks merusak etika dialog — tantangan musyawarah di era digital."},
{"id":"TWK-3394","q":"Sila keempat Pancasila menempatkan musyawarah di atas voting karena ....","opts":["mufakat mencerminkan kebersamaan dan menghargai semua pihak","voting dilarang dalam ajaran Pancasila","musyawarah selalu menghasilkan keputusan tercepat","voting hanya berlaku di negara liberal","mufakat berarti suara minoritas harus dibungkam"],"a":0,"ex":"Mufakat diutamakan karena merangkul semua pihak; voting adalah alternatif terakhir, bukan dilarang."},
{"id":"TWK-3395","q":"Pengamalan sila keempat Pancasila oleh mahasiswa dalam organisasi kampus ditunjukkan dengan ....","opts":["menyusun program kerja melalui rapat dan musyawarah anggota","ketua organisasi menentukan semua program sendirian","anggota dipaksa iuran tanpa musyawarah terlebih dahulu","rapat hanya dihadiri pengurus inti yang itu-itu saja","keputusan organisasi tidak pernah disosialisasikan"],"a":0,"ex":"Program kerja hasil musyawarah anggota adalah demokrasi Pancasila di kampus."},
{"id":"TWK-3396","q":"Nilai kerakyatan dalam sila keempat Pancasila bersumber dari ....","opts":["nilai demokrasi yang telah hidup dalam budaya gotong royong bangsa Indonesia","sistem demokrasi liberal negara-negara Barat","paham komunisme yang menekankan kolektivitas","keputusan sepihak para pendiri negara","pengaruh sistem kasta dalam masyarakat"],"a":0,"ex":"Kerakyatan Pancasila digali dari budaya gotong royong dan musyawarah bangsa sendiri, bukan tiruan Barat."},
{"id":"TWK-3397","q":"Seorang anggota dewan memperjuangkan aspirasi konstituennya dalam rapat paripurna. Perilaku tersebut selaras dengan Pancasila sila ....","opts":["keempat","pertama","kedua","ketiga","kelima"],"a":0,"ex":"Memperjuangkan aspirasi rakyat di parlemen adalah fungsi perwakilan — wujud sila keempat."},
{"id":"TWK-3398","q":"Dalam sila keempat Pancasila, kebebasan berpendapat dibatasi oleh ....","opts":["tanggung jawab moral dan penghormatan terhadap hak orang lain","keinginan penguasa yang sedang berkuasa","kepentingan pemilik media massa","tekanan kelompok mayoritas semata","aturan yang dibuat sepihak oleh aparat"],"a":0,"ex":"Kebebasan berpendapat dalam demokrasi Pancasila disertai tanggung jawab dan hormat pada hak orang lain."},
{"id":"TWK-3399","q":"Sila keempat Pancasila menjadi pedoman dalam menyelesaikan konflik sosial melalui ....","opts":["dialog dan musyawarah yang mengedepankan win-win solution","kekerasan agar salah satu pihak menyerah","pembiaran konflik hingga mereda sendiri","campur tangan kekuatan asing","pengusiran salah satu pihak yang bersengketa"],"a":0,"ex":"Konflik sosial diselesaikan lewat dialog-musyarawah win-win — bukan kekerasan."},
{"id":"TWK-3400","q":"Makna terdalam sila keempat Pancasila bagi kehidupan berbangsa adalah ....","opts":["rakyat adalah pemegang kedaulatan tertinggi yang berpartisipasi lewat musyawarah","negara dikuasai segelintir elite tanpa peran rakyat","musyawarah hanya simbol tanpa makna nyata","kedaulatan rakyat dialihkan kepada lembaga asing","rakyat cukup menjadi penonton pembangunan"],"a":0,"ex":"Inti sila keempat: kedaulatan di tangan rakyat, diwujudkan lewat partisipasi dan permusyawaratan."},
{"id":"TWK-3401","q":"Bunyi sila kelima Pancasila adalah ....","opts":["Keadilan sosial bagi seluruh rakyat Indonesia","Ketuhanan Yang Maha Esa","Kemanusiaan yang adil dan beradab","Persatuan Indonesia","Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan"],"a":0,"ex":"Sila kelima berbunyi 'Keadilan sosial bagi seluruh rakyat Indonesia' — tujuan akhir seluruh sila Pancasila."},
{"id":"TWK-3402","q":"Makna 'keadilan sosial' dalam sila kelima Pancasila adalah ....","opts":["terwujudnya keseimbangan antara hak dan kewajiban serta pemerataan kesejahteraan bagi seluruh rakyat","semua warga negara menerima jumlah harta yang sama persis","keadilan hanya ditegakkan bagi golongan mampu","kesejahteraan hanya untuk penduduk kota besar","hak warga negara boleh dikurangi demi pembangunan"],"a":0,"ex":"Keadilan sosial = keseimbangan hak-kewajiban dan pemerataan kesejahteraan, bukan penyeragaman harta."},
{"id":"TWK-3403","q":"Di sebuah kelas, guru membagi tugas piket secara merata dan memberi kesempatan yang sama kepada setiap siswa untuk menjadi ketua kelas. Praktik tersebut menanamkan nilai Pancasila sila ....","opts":["kelima","pertama","kedua","ketiga","keempat"],"a":0,"ex":"Pembagian tugas dan kesempatan yang merata menanamkan rasa keadilan — sila kelima."},
{"id":"TWK-3404","q":"Perilaku yang bertentangan dengan sila kelima Pancasila adalah ....","opts":["melakukan korupsi dana bantuan sosial untuk korban bencana","ikut serta dalam program padat karya di desanya","membayar upah pekerja tepat waktu dan layak","memberikan santunan kepada anak yatim","menghormati hak milik orang lain"],"a":0,"ex":"Korupsi bansos merampas hak rakyat miskin — pelanggaran berat sila kelima."},
{"id":"TWK-3405","q":"Sila kelima Pancasila menjadi tujuan dari keempat sila sebelumnya karena ....","opts":["seluruh nilai Pancasila bermuara pada terwujudnya masyarakat adil dan makmur","sila kelima lebih penting sehingga sila lain boleh diabaikan","hanya sila kelima yang wajib diamalkan","sila-sila lain tidak berkaitan dengan keadilan","keadilan sosial dapat dicapai tanpa sila-sila lain"],"a":0,"ex":"Sila kelima adalah muara: ketuhanan, kemanusiaan, persatuan, dan kerakyatan diabdikan bagi keadilan sosial seluruh rakyat."},
{"id":"TWK-3406","q":"Wujud keadilan sosial dalam sila kelima Pancasila di bidang pendidikan adalah ....","opts":["setiap anak Indonesia berhak memperoleh pendidikan yang layak tanpa diskriminasi","pendidikan berkualitas hanya untuk anak orang kaya","anak daerah terpencil tidak perlu bersekolah","beasiswa hanya diberikan kepada anak pejabat","sekolah gratis menghapus seluruh biaya tanpa terkecuali"],"a":0,"ex":"Pemerataan akses pendidikan layak bagi semua anak adalah keadilan sosial di bidang pendidikan."},
{"id":"TWK-3407","q":"Seorang pengusaha membayar upah di bawah standar dan mempekerjakan anak di bawah umur. Tindakan tersebut melanggar Pancasila sila ....","opts":["kelima","pertama","kedua","ketiga","keempat"],"a":0,"ex":"Upah tidak layak dan eksploitasi anak merampas keadilan bagi pekerja — pelanggaran sila kelima."},
{"id":"TWK-3408","q":"Program pemerintah berupa bantuan langsung tunai bagi keluarga miskin merupakan perwujudan sila kelima Pancasila karena ....","opts":["negara hadir menjamin kesejahteraan warga yang kurang mampu","bantuan tunai membuat rakyat menjadi malas bekerja","program bantuan hanya pencitraan pemerintah","rakyat miskin tidak berhak menerima bantuan","bantuan sosial merugikan perekonomian negara"],"a":0,"ex":"BLT adalah wujud negara menjamin kesejahteraan warganya — pengamalan sila kelima."},
{"id":"TWK-3409","q":"Kesenjangan ekonomi yang sangat lebar antara si kaya dan si miskin bertentangan dengan sila kelima Pancasila sehingga negara wajib ....","opts":["melakukan pemerataan pembangunan dan pemberdayaan ekonomi rakyat","membiarkan kesenjangan karena hukum alam","mengambil seluruh harta orang kaya","melarang warga menjadi kaya raya","menyerahkan sepenuhnya pada mekanisme pasar"],"a":0,"ex":"Negara wajib memeratakan pembangunan dan memberdayakan ekonomi rakyat — bukan membiarkan atau merampas."},
{"id":"TWK-3410","q":"Sikap adil dalam sila kelima Pancasila apabila diterapkan seorang guru dalam menilai siswa berarti ....","opts":["menilai berdasarkan kemampuan dan usaha masing-masing siswa secara objektif","memberi nilai bagus hanya kepada siswa yang disukainya","menilai semua siswa dengan nilai yang sama rata","memberi nilai rendah agar siswa rajin belajar","menilai berdasarkan kekayaan orang tua siswa"],"a":0,"ex":"Adil dalam penilaian = objektif sesuai kemampuan dan usaha, bukan pilih kasih atau sama rata."},
{"id":"TWK-3411","q":"Gotong royong membangun rumah warga yang terkena musibah merupakan pengamalan sila kelima Pancasila karena ....","opts":["mewujudkan kepedulian dan keadilan sosial bagi sesama yang membutuhkan","gotong royong hanya menguntungkan pihak tertentu","musibah adalah urusan pribadi masing-masing","membantu orang lain merugikan diri sendiri","kegiatan sosial tidak ada kaitannya dengan Pancasila"],"a":0,"ex":"Gotong royong menolong yang terkena musibah adalah keadilan sosial dalam tindakan nyata."},
{"id":"TWK-3412","q":"Praktik pungutan liar dalam pelayanan publik bertentangan dengan sila kelima Pancasila karena ....","opts":["membebani rakyat kecil dan merusak keadilan dalam pelayanan","pungli mempercepat proses pelayanan publik","rakyat wajib membayar lebih untuk pelayanan baik","pungli adalah tradisi yang harus dilestarikan","pelayanan gratis tidak mungkin diwujudkan"],"a":0,"ex":"Pungli membebani rakyat kecil dan merusak keadilan pelayanan — pelanggaran sila kelima."},
{"id":"TWK-3413","q":"Seorang siswa membagi bekal makan siangnya dengan teman yang tidak membawa bekal. Perbuatan tersebut mencerminkan Pancasila sila ....","opts":["kelima","pertama","kedua","ketiga","keempat"],"a":0,"ex":"Berbagi dengan yang membutuhkan adalah benih keadilan sosial — sila kelima."},
{"id":"TWK-3414","q":"Dalam sila kelima Pancasila, frasa 'bagi seluruh rakyat Indonesia' menegaskan bahwa keadilan harus ....","opts":["dinikmati merata oleh seluruh warga tanpa terkecuali","hanya dirasakan penduduk pulau Jawa","diprioritaskan bagi aparatur negara","dibatasi bagi warga yang taat pajak","diberikan berdasarkan kedekatan dengan penguasa"],"a":0,"ex":"'Seluruh rakyat Indonesia' = keadilan tanpa kecuali, dari Sabang sampai Merauke."},
{"id":"TWK-3415","q":"Hubungan sila kelima dengan sila kedua Pancasila adalah ....","opts":["penghormatan terhadap kemanusiaan diwujudkan dalam keadilan sosial bagi semua","keduanya tidak memiliki keterkaitan makna","sila kelima menghapus nilai kemanusiaan","kemanusiaan hanya berlaku bagi golongan tertentu","keadilan sosial tidak memerlukan nilai kemanusiaan"],"a":0,"ex":"Kemanusiaan (sila 2) yang adil dan beradab bermuara pada keadilan sosial (sila 5)."},
{"id":"TWK-3416","q":"Bentuk pengamalan sila kelima Pancasila di era digital adalah ....","opts":["tidak melakukan penipuan dalam jual beli daring dan menghargai hak konsumen","menjual barang palsu dengan foto asli di marketplace","menyebarkan data pribadi pembeli ke pihak lain","melakukan phishing untuk menguras rekening orang","membajak karya digital orang lain untuk dijual"],"a":0,"ex":"Jujur dalam jual beli daring dan menghargai hak konsumen adalah keadilan sosial di ruang digital."},
{"id":"TWK-3417","q":"Pembangunan infrastruktur yang merata hingga ke daerah terpencil merupakan pengamalan sila kelima Pancasila karena ....","opts":["setiap warga berhak menikmati hasil pembangunan secara adil","pembangunan hanya perlu difokuskan di kota besar","daerah terpencil tidak berkontribusi pada negara","infrastruktur desa menghambat kemajuan kota","pemerataan pembangunan merugikan daerah maju"],"a":0,"ex":"Pemerataan infrastruktur menjamin keadilan pembangunan bagi seluruh rakyat Indonesia."},
{"id":"TWK-3418","q":"Seorang pejabat membagikan proyek pemerintah hanya kepada kerabatnya. Perbuatan tersebut melanggar Pancasila sila ....","opts":["kelima","pertama","kedua","ketiga","keempat"],"a":0,"ex":"Nepotisme proyek merampas kesempatan adil bagi semua — pelanggaran sila kelima."},
{"id":"TWK-3419","q":"Nilai keadilan dalam sila kelima Pancasila mencakup keadilan di bidang ....","opts":["hukum, ekonomi, sosial, dan politik secara menyeluruh","hukum pidana semata","ekonomi bagi pengusaha besar saja","politik bagi para pejabat saja","sosial bagi golongan tertentu saja"],"a":0,"ex":"Keadilan Pancasila bersifat menyeluruh: hukum, ekonomi, sosial, dan politik."},
{"id":"TWK-3420","q":"Sikap yang mencerminkan sila kelima Pancasila dalam pembagian warisan keluarga adalah ....","opts":["membagi warisan secara adil sesuai ketentuan hukum dan kesepakatan keluarga","anak tertua mengambil seluruh harta warisan","harta warisan disembunyikan dari anggota keluarga lain","pembagian warisan diputuskan dengan kekerasan","ahli waris perempuan tidak diberi bagian sama sekali"],"a":0,"ex":"Pembagian warisan yang adil sesuai hukum dan musyawarah keluarga adalah sila kelima di rumah."},
{"id":"TWK-3421","q":"Sila kelima Pancasila menuntut keseimbangan antara ....","opts":["hak yang diterima dan kewajiban yang dilaksanakan setiap warga negara","kepentingan individu dan penghapusan kepentingan umum","kebebasan mutlak dan pengekangan total","hak warga dan pengabaian kewajiban","kewajiban negara dan peniadaan hak rakyat"],"a":0,"ex":"Keadilan sosial = keseimbangan hak dan kewajiban, tidak berat sebelah."},
{"id":"TWK-3422","q":"Aksi demonstrasi buruh menuntut upah layak berkaitan dengan Pancasila sila ....","opts":["kelima","pertama","kedua","ketiga","keempat"],"a":0,"ex":"Tuntutan upah layak adalah perjuangan keadilan sosial bagi pekerja — sila kelima."},
{"id":"TWK-3423","q":"Pengamalan sila kelima Pancasila oleh generasi muda dapat diwujudkan dengan ....","opts":["tidak melakukan perundungan dan memperlakukan semua teman secara adil","memalak teman yang lemah setiap hari","memilih teman berdasarkan merek pakaian","menyebarkan gosip untuk menjatuhkan teman","mengucilkan teman yang berbeda status sosial"],"a":0,"ex":"Memperlakukan semua teman secara adil tanpa memandang status adalah sila kelima di kalangan pelajar."},
{"id":"TWK-3424","q":"Tujuan nasional 'memajukan kesejahteraan umum' dalam Pembukaan UUD 1945 merupakan penjabaran dari Pancasila sila ....","opts":["kelima","pertama","kedua","ketiga","keempat"],"a":0,"ex":"'Kesejahteraan umum' adalah rumusan konstitusional dari keadilan sosial — sila kelima."},
{"id":"TWK-3425","q":"Makna terdalam sila kelima Pancasila bagi bangsa Indonesia adalah ....","opts":["cita-cita terwujudnya masyarakat adil, makmur, dan sejahtera bagi semua","keadilan hanya menjadi slogan tanpa perlu diwujudkan","kesejahteraan cukup dinikmati segelintir orang","rakyat harus menerima nasibnya masing-masing","negara tidak bertanggung jawab atas kesejahteraan rakyat"],"a":0,"ex":"Sila kelima adalah cita-cita: masyarakat Indonesia yang adil, makmur, dan sejahtera seluruhnya."},
{"id":"TWK-3426","q":"Arti nama Jepang BPUPKI, Dokuritsu Junbi Cosakai, adalah ....","opts":["Badan Penyelidik Usaha-Usaha Persiapan Kemerdekaan","Badan Persiapan Kemerdekaan Indonesia","Dewan Pertimbangan Agung","Badan Keamanan Rakyat","Komite Nasional Indonesia"],"a":0,"ex":"Dokuritsu Junbi Cosakai = Badan Penyelidik Usaha-Usaha Persiapan Kemerdekaan (BPUPKI)."},
{"id":"TWK-3427","q":"BPUPKI mengadakan sidang sebanyak ....","opts":["dua kali","satu kali","tiga kali","empat kali","lima kali"],"a":0,"ex":"BPUPKI bersidang dua kali: 29 Mei–1 Juni 1945 (dasar negara) dan 10–17 Juli 1945 (rancangan UUD)."},
{"id":"TWK-3428","q":"Sidang pertama BPUPKI membahas tentang ....","opts":["dasar negara Indonesia merdeka","strategi pertempuran 10 November","pembentukan tentara nasional","sistem mata uang Indonesia","hubungan dagang dengan Jepang"],"a":0,"ex":"Sidang I BPUPKI (29 Mei–1 Juni 1945) membahas dasar negara — melahirkan usulan-usulan Pancasila."},
{"id":"TWK-3429","q":"Mr. Muhammad Yamin mengusulkan lima asas dasar negara dalam sidang BPUPKI pada tanggal ....","opts":["29 Mei 1945","31 Mei 1945","1 Juni 1945","22 Juni 1945","18 Agustus 1945"],"a":0,"ex":"Yamin berpidato 29 Mei 1945 dengan lima asas: Peri Kebangsaan, Peri Kemanusiaan, Peri Ketuhanan, Peri Kerakyatan, Kesejahteraan Rakyat."},
{"id":"TWK-3430","q":"Lima asas usulan Mr. Muhammad Yamin pada sidang BPUPKI adalah ....","opts":["Peri Kebangsaan, Peri Kemanusiaan, Peri Ketuhanan, Peri Kerakyatan, Kesejahteraan Rakyat","Ketuhanan, Kemanusiaan, Persatuan, Kerakyatan, Keadilan","Nasionalisme, Internasionalisme, Demokrasi, Keadilan Sosial, Ketuhanan","Persatuan, Kekeluargaan, Keseimbangan, Musyawarah, Keadilan","Kebangsaan, Perikemanusiaan, Mufakat, Kesejahteraan, Ketuhanan"],"a":0,"ex":"Usulan Yamin (29 Mei 1945): lima 'Peri' — Kebangsaan, Kemanusiaan, Ketuhanan, Kerakyatan, ditambah Kesejahteraan Rakyat."},
{"id":"TWK-3431","q":"Pandangan negara integralistik dalam sidang BPUPKI dikemukakan oleh ....","opts":["Mr. Soepomo","Mr. Muhammad Yamin","Ir. Soekarno","Drs. Moh. Hatta","Mr. Ahmad Soebardjo"],"a":0,"ex":"Soepomo mengusung negara integralistik: negara menyatu dengan rakyat, menolak individualisme liberal."},
{"id":"TWK-3432","q":"Pokok-pokok usulan dasar negara Mr. Soepomo dalam sidang BPUPKI adalah ....","opts":["Persatuan, Kekeluargaan, Keseimbangan lahir dan batin, Musyawarah, Keadilan rakyat","Peri Kebangsaan, Peri Kemanusiaan, Peri Ketuhanan, Peri Kerakyatan, Kesejahteraan Rakyat","Kebangsaan Indonesia, Internasionalisme, Mufakat, Kesejahteraan Sosial, Ketuhanan","Ketuhanan, Kemanusiaan, Persatuan, Kerakyatan, Keadilan Sosial","Nasionalisme, Humanisme, Demokrasi, Keadilan, Ketuhanan"],"a":0,"ex":"Usulan Soepomo: Persatuan, Kekeluargaan, Keseimbangan lahir-batin, Musyawarah, Keadilan rakyat (negara integralistik)."},
{"id":"TWK-3433","q":"Ir. Soekarno menyampaikan pidato tentang dasar negara dalam sidang BPUPKI pada tanggal ....","opts":["1 Juni 1945","29 Mei 1945","31 Mei 1945","22 Juni 1945","17 Agustus 1945"],"a":0,"ex":"Pidato Soekarno 1 Juni 1945 melahirkan istilah 'Pancasila' — diperingati sebagai Hari Lahir Pancasila."},
{"id":"TWK-3434","q":"Lima dasar usulan Ir. Soekarno yang kemudian disebut Pancasila adalah ....","opts":["Kebangsaan Indonesia, Internasionalisme, Mufakat, Kesejahteraan Sosial, Ketuhanan yang berkebudayaan","Peri Kebangsaan, Peri Kemanusiaan, Peri Ketuhanan, Peri Kerakyatan, Kesejahteraan Rakyat","Persatuan, Kekeluargaan, Keseimbangan lahir dan batin, Musyawarah, Keadilan rakyat","Ketuhanan, Kemanusiaan, Persatuan, Kerakyatan, Keadilan Sosial","Nasionalisme, Liberalisme, Sosialisme, Demokrasi, Teokrasi"],"a":0,"ex":"Usulan Soekarno 1 Juni 1945: Kebangsaan, Internasionalisme/Perikemanusiaan, Mufakat/Demokrasi, Kesejahteraan Sosial, Ketuhanan yang berkebudayaan."},
{"id":"TWK-3435","q":"Istilah 'Pancasila' pertama kali dikemukakan oleh ....","opts":["Ir. Soekarno","Mr. Muhammad Yamin","Mr. Soepomo","Drs. Moh. Hatta","Mr. Ahmad Soebardjo"],"a":0,"ex":"Soekarno mengemukakan istilah 'Pancasila' (panca = lima, sila = dasar) dalam pidatonya 1 Juni 1945."},
{"id":"TWK-3436","q":"Tanggal 1 Juni diperingati sebagai Hari Lahir Pancasila berdasarkan ....","opts":["pidato Ir. Soekarno tentang Pancasila dalam sidang BPUPKI","proklamasi kemerdekaan Indonesia","pengesahan UUD 1945 oleh PPKI","pembentukan Panitia Sembilan","penandatanganan Piagam Jakarta"],"a":0,"ex":"1 Juni 1945 = hari pidato Soekarno mengusulkan Pancasila; ditetapkan sebagai Hari Lahir Pancasila (Keppres 24/2016)."},
{"id":"TWK-3437","q":"Wakil ketua BPUPKI dari pihak Indonesia adalah ....","opts":["R.P. Soeroso","Ichibangase","Ir. Soekarno","Drs. Moh. Hatta","Mr. Soepomo"],"a":0,"ex":"BPUPKI diketuai dr. Radjiman; wakilnya Ichibangase (Jepang) dan R.P. Soeroso (Indonesia)."},
{"id":"TWK-3438","q":"Panitia Sembilan dibentuk BPUPKI dengan tugas ....","opts":["merumuskan dasar negara berdasarkan usulan-usulan dalam sidang","menyusun strategi perang gerilya","membentuk pasukan keamanan rakyat","mengatur pembagian wilayah Indonesia","menyusun anggaran dasar organisasi"],"a":0,"ex":"Panitia Sembilan (dibentuk 22 Juni 1945) merumuskan dasar negara — hasilnya Piagam Jakarta."},
{"id":"TWK-3439","q":"Tokoh yang menjadi ketua Panitia Sembilan perumus Pancasila adalah ....","opts":["Ir. Soekarno","Drs. Moh. Hatta","Mr. Muhammad Yamin","Mr. Soepomo","KH. Wahid Hasyim"],"a":0,"ex":"Panitia Sembilan diketuai Ir. Soekarno dengan Hatta sebagai wakil ketua."},
{"id":"TWK-3440","q":"Anggota Panitia Sembilan perumus dasar negara Pancasila dari golongan Islam antara lain ....","opts":["KH. Wahid Hasyim dan Ki Bagus Hadikusumo","Ir. Soekarno dan Drs. Moh. Hatta","Mr. Soepomo dan Mr. Ahmad Soebardjo","Mr. Muhammad Yamin dan Abikoesno Tjokrosoejoso","A.A. Maramis dan Achmad Soebardjo"],"a":0,"ex":"Wakil golongan Islam: KH. Wahid Hasyim, Ki Bagus Hadikusumo, Kahar Muzakkir, dan H. Agus Salim."},
{"id":"TWK-3441","q":"Dokumen Panitia Sembilan tertanggal 22 Juni 1945 yang memuat rumusan awal sila-sila Pancasila dikenal dengan nama ....","opts":["Piagam Jakarta","Piagam Madinah","Deklarasi Djuanda","Maklumat 3 November","Perjanjian Linggarjati"],"a":0,"ex":"Rumusan 22 Juni 1945 dikenal sebagai Piagam Jakarta (Jakarta Charter) — cikal bakal Pembukaan UUD 1945."},
{"id":"TWK-3442","q":"Bunyi sila pertama dalam Piagam Jakarta sebelum diubah adalah ....","opts":["Ketuhanan dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya","Ketuhanan Yang Maha Esa","Ketuhanan yang berkebudayaan","Kepercayaan terhadap Tuhan Yang Maha Esa","Ketuhanan menurut dasar kemanusiaan yang adil"],"a":0,"ex":"Piagam Jakarta memuat sila pertama dengan 'tujuh kata' kewajiban syariat Islam — diubah pada 18 Agustus 1945."},
{"id":"TWK-3443","q":"Perubahan sila pertama Piagam Jakarta menjadi 'Ketuhanan Yang Maha Esa' dilakukan pada ....","opts":["18 Agustus 1945 dalam sidang PPKI","22 Juni 1945 dalam Panitia Sembilan","1 Juni 1945 dalam sidang BPUPKI","17 Agustus 1945 saat proklamasi","29 Mei 1945 dalam sidang BPUPKI"],"a":0,"ex":"Sidang PPKI 18 Agustus 1945 mengubah tujuh kata Piagam Jakarta menjadi 'Ketuhanan Yang Maha Esa'."},
{"id":"TWK-3444","q":"Perwira Jepang yang menjadi perantara kabar keberatan Indonesia Timur tentang tujuh kata Piagam Jakarta adalah ....","opts":["Nishijima","Terauchi","Maeda","Yamamoto","Suzuki"],"a":0,"ex":"Hatta menerima kabar keberatan lewat perwira kaigun Nishijima, lalu mengusulkan perubahan tujuh kata Piagam Jakarta."},
{"id":"TWK-3445","q":"Alasan perubahan sila pertama Piagam Jakarta adalah ....","opts":["agar seluruh rakyat Indonesia dari berbagai agama merasa terangkul dalam NKRI","karena golongan Islam menolak rumusan tersebut","agar Indonesia menjadi negara sekuler","karena desakan pemerintah pendudukan Jepang","agar Pancasila sama dengan ideologi negara lain"],"a":0,"ex":"Perubahan dilakukan demi persatuan: Indonesia Timur (mayoritas nonmuslim) mengancam memisahkan diri bila tujuh kata dipertahankan."},
{"id":"TWK-3446","q":"Sidang kedua BPUPKI membahas tentang ....","opts":["rancangan Undang-Undang Dasar","dasar negara Indonesia","strategi perang Asia Timur Raya","pembentukan kementerian","sistem perekonomian nasional"],"a":0,"ex":"Sidang II BPUPKI (10–17 Juli 1945) membahas RUU Dasar — membentuk Panitia Perancang UUD."},
{"id":"TWK-3447","q":"Panitia Perancang UUD dalam sidang kedua BPUPKI diketuai oleh ....","opts":["Ir. Soekarno","Drs. Moh. Hatta","Mr. Soepomo","Mr. Muhammad Yamin","dr. Radjiman Wedyodiningrat"],"a":0,"ex":"Panitia Perancang UUD (38 anggota) diketuai Ir. Soekarno."},
{"id":"TWK-3448","q":"BPUPKI dibubarkan dan digantikan oleh PPKI pada tanggal ....","opts":["7 Agustus 1945","17 Agustus 1945","18 Agustus 1945","1 Juni 1945","22 Juni 1945"],"a":0,"ex":"BPUPKI dibubarkan 7 Agustus 1945, digantikan PPKI (Dokuritsu Junbi Inkai) yang diketuai Soekarno."},
{"id":"TWK-3449","q":"Perbedaan mendasar BPUPKI dan PPKI adalah ....","opts":["BPUPKI badan bentukan Jepang sedangkan PPKI murni bentukan bangsa Indonesia","BPUPKI membahas UUD sedangkan PPKI membahas dasar negara","BPUPKI beranggotakan orang Jepang sedangkan PPKI orang Indonesia","keduanya tidak memiliki perbedaan sama sekali","PPKI dibentuk sebelum BPUPKI"],"a":0,"ex":"BPUPKI bentukan Jepang (badan penyelidik); PPKI bentukan bangsa Indonesia sendiri untuk menyiapkan kemerdekaan."},
{"id":"TWK-3450","q":"Semangat yang melandasi para tokoh BPUPKI dalam merumuskan Pancasila adalah ....","opts":["persatuan dan kesatuan demi Indonesia merdeka yang berdaulat","kepentingan golongan masing-masing","keinginan menyenangkan pemerintah Jepang","persaingan antar tokoh untuk menjadi pemimpin","balas dendam terhadap penjajah"],"a":0,"ex":"Meski berbeda pandangan, para tokoh BPUPKI disatukan semangat persatuan demi Indonesia merdeka."},
{"id":"TWK-3451","q":"PPKI mengadakan sidang pertama pada tanggal ....","opts":["18 Agustus 1945","17 Agustus 1945","22 Juni 1945","7 Agustus 1945","1 Juni 1945"],"a":0,"ex":"Sidang I PPKI 18 Agustus 1945: mengesahkan UUD 1945, memilih presiden-wakil presiden, dan membentuk KNIP."},
{"id":"TWK-3452","q":"Selain mengesahkan UUD 1945, sidang PPKI 18 Agustus 1945 juga memutuskan ....","opts":["memilih Soekarno-Hatta sebagai presiden dan wakil presiden RI","memproklamasikan kemerdekaan Indonesia","membentuk Tentara Nasional Indonesia","menetapkan lagu kebangsaan Indonesia Raya","membubarkan BPUPKI"],"a":0,"ex":"Sidang PPKI 18 Agustus 1945: mengesahkan UUD 1945, memilih Soekarno-Hatta, dan membentuk KNIP."},
{"id":"TWK-3453","q":"Rumusan Pancasila yang sah dan resmi sebagai dasar negara adalah yang tercantum dalam ....","opts":["Pembukaan UUD 1945 alinea keempat","Piagam Jakarta 22 Juni 1945","pidato Ir. Soekarno 1 Juni 1945","pidato Mr. Muhammad Yamin 29 Mei 1945","naskah proklamasi kemerdekaan"],"a":0,"ex":"Rumusan resmi Pancasila adalah yang disahkan PPKI dalam Pembukaan UUD 1945 alinea IV — bukan rumusan pidato atau Piagam Jakarta."},
{"id":"TWK-3454","q":"Pancasila tercantum dalam Pembukaan UUD 1945 pada alinea ....","opts":["keempat","pertama","kedua","ketiga","kelima"],"a":0,"ex":"Pancasila dirumuskan dalam Pembukaan UUD 1945 alinea keempat."},
{"id":"TWK-3455","q":"Dalam sidang PPKI 18 Agustus 1945, yang terpilih sebagai presiden dan wakil presiden RI adalah ....","opts":["Ir. Soekarno dan Drs. Moh. Hatta","Mr. Soepomo dan Mr. Ahmad Soebardjo","dr. Radjiman dan R.P. Soeroso","Mr. Muhammad Yamin dan Ki Bagus Hadikusumo","KH. Wahid Hasyim dan Abikoesno Tjokrosoejoso"],"a":0,"ex":"Sidang PPKI 18 Agustus 1945 memilih Soekarno-Hatta sebagai presiden dan wakil presiden pertama RI."},
{"id":"TWK-3456","q":"KNIP yang dibentuk dalam sidang PPKI merupakan singkatan dari ....","opts":["Komite Nasional Indonesia Pusat","Kantor Negara Indonesia Pusat","Komisi Nasional Indonesia Pusat","Kementerian Negara Indonesia Pusat","Konsulat Negara Indonesia Pusat"],"a":0,"ex":"KNIP (Komite Nasional Indonesia Pusat) dibentuk 18 Agustus 1945 sebagai pembantu presiden sebelum MPR/DPR terbentuk."},
{"id":"TWK-3457","q":"Perubahan redaksional Piagam Jakarta menjadi Pembukaan UUD 1945 menunjukkan sifat Pancasila sebagai ....","opts":["ideologi yang mampu menampung kemajemukan bangsa Indonesia","dasar negara yang kaku dan tidak dapat diubah","ideologi yang hanya menguntungkan golongan tertentu","rumusan yang gagal disepakati para pendiri bangsa","dokumen yang tidak memiliki kekuatan hukum"],"a":0,"ex":"Perubahan tujuh kata demi merangkul semua golongan menunjukkan Pancasila sebagai pemersatu kemajemukan."},
{"id":"TWK-3458","q":"Tokoh yang dikenal sebagai 'Bapak Pancasila' karena mengusulkan istilah dan rumusan Pancasila adalah ....","opts":["Ir. Soekarno","Drs. Moh. Hatta","Mr. Muhammad Yamin","Mr. Soepomo","Jenderal Soedirman"],"a":0,"ex":"Soekarno dijuluki Bapak Pancasila karena mengemukakan istilah dan rumusan Pancasila pada 1 Juni 1945."},
{"id":"TWK-3459","q":"Sidang PPKI kedua dilaksanakan pada tanggal ....","opts":["19 Agustus 1945","18 Agustus 1945","20 Agustus 1945","22 Agustus 1945","17 Agustus 1945"],"a":0,"ex":"Sidang II PPKI 19 Agustus 1945 membahas pembagian wilayah (8 provinsi) dan kementerian."},
{"id":"TWK-3460","q":"Hasil sidang PPKI tanggal 19 Agustus 1945 antara lain ....","opts":["pembentukan 8 provinsi dan 12 kementerian","pengesahan UUD 1945","pemilihan presiden dan wakil presiden","perubahan Piagam Jakarta","pembubaran KNIP"],"a":0,"ex":"Sidang 19 Agustus 1945: Indonesia dibagi 8 provinsi dan dibentuk 12 kementerian/departemen."},
{"id":"TWK-3461","q":"Delapan provinsi pertama yang dibentuk PPKI pada 19 Agustus 1945 dipimpin oleh seorang ....","opts":["gubernur","bupati","wali kota","camat","lurah"],"a":0,"ex":"Delapan provinsi pertama masing-masing dipimpin gubernur yang ditunjuk PPKI."},
{"id":"TWK-3462","q":"Sidang PPKI ketiga pada 22 Agustus 1945 menghasilkan keputusan tentang ....","opts":["pembentukan KNIP, PNI, dan BKR","pengesahan UUD 1945","pemilihan presiden RI","perubahan sila pertama Pancasila","pembagian wilayah provinsi"],"a":0,"ex":"Sidang III PPKI (22 Agustus 1945): membentuk KNIP, Partai Nasional Indonesia, dan Badan Keamanan Rakyat."},
{"id":"TWK-3463","q":"BKR yang dibentuk PPKI merupakan singkatan dari ....","opts":["Badan Keamanan Rakyat","Barisan Kebangsaan Rakyat","Badan Ketahanan Rakyat","Brigade Keamanan Republik","Benteng Kedaulatan Rakyat"],"a":0,"ex":"BKR (Badan Keamanan Rakyat) dibentuk 22 Agustus 1945 — cikal bakal TNI."},
{"id":"TWK-3464","q":"Pengesahan Pancasila sebagai dasar negara terjadi bersamaan dengan peristiwa ....","opts":["disahkannya UUD 1945 oleh PPKI","dibacakannya proklamasi kemerdekaan","dibentuknya Panitia Sembilan","disampaikannya pidato 1 Juni 1945","ditandatanganinya Piagam Jakarta"],"a":0,"ex":"Pancasila disahkan 18 Agustus 1945 bersamaan dengan pengesahan UUD 1945 oleh PPKI."},
{"id":"TWK-3465","q":"Naskah proklamasi yang memuat cita-cita bangsa sejiwa dengan Pancasila diketik oleh ....","opts":["Sayuti Melik","B.M. Diah","Sukarni","Chaerul Saleh","Adam Malik"],"a":0,"ex":"Sayuti Melik mengetik naskah proklamasi yang ditulis tangan Soekarno di rumah Laksamana Maeda."},
{"id":"TWK-3466","q":"Rumusan Pancasila dalam Pembukaan UUD 1945 bersifat final karena ....","opts":["telah disahkan PPKI sebagai representasi seluruh rakyat Indonesia","tidak boleh dibahas dalam forum ilmiah mana pun","ditulis langsung oleh Presiden Soekarno","disalin dari konstitusi negara lain","ditetapkan oleh pemerintah pendudukan Jepang"],"a":0,"ex":"Rumusan Pembukaan UUD 1945 (termasuk Pancasila) bersifat final karena disahkan PPKI mewakili seluruh bangsa."},
{"id":"TWK-3467","q":"Peran Drs. Moh. Hatta dalam perumusan Pancasila yang paling dikenang adalah ....","opts":["mengusulkan perubahan tujuh kata Piagam Jakarta demi persatuan nasional","mengusulkan istilah Pancasila pertama kali","memimpin sidang pertama BPUPKI","mengetik naskah proklamasi kemerdekaan","membentuk Panitia Sembilan"],"a":0,"ex":"Peran monumental Hatta: melobi perubahan tujuh kata Piagam Jakarta sehingga NKRI tetap utuh."},
{"id":"TWK-3468","q":"Apabila tujuh kata dalam Piagam Jakarta tidak diubah, dampak yang paling mungkin terjadi adalah ....","opts":["Indonesia Timur memisahkan diri dari NKRI","Indonesia menjadi negara maju lebih cepat","seluruh rakyat Indonesia memeluk satu agama","Belanda kembali menjajah Indonesia","Pancasila tidak jadi disahkan"],"a":0,"ex":"Utusan Indonesia Timur (melalui Nishijima) menyatakan keberatan keras — NKRI terancam pecah bila tujuh kata dipertahankan."},
{"id":"TWK-3469","q":"Nilai historis Pancasila sebagai dasar negara terletak pada ....","opts":["proses perumusannya yang melibatkan musyawarah seluruh golongan bangsa","kecepatan perumusannya yang hanya satu hari","ditetapkan tanpa melalui pembahasan apa pun","diimpor dari ideologi negara lain","hanya dirumuskan oleh satu orang tokoh"],"a":0,"ex":"Nilai historis Pancasila: lahir dari musyawarah para pendiri bangsa yang mewakili berbagai golongan."},
{"id":"TWK-3470","q":"Tokoh perumus Pancasila yang berasal dari golongan kebangsaan (nasionalis sekuler) adalah ....","opts":["Ir. Soekarno","KH. Wahid Hasyim","Ki Bagus Hadikusumo","Kahar Muzakkir","H. Agus Salim"],"a":0,"ex":"Soekarno mewakili golongan kebangsaan; KH. Wahid Hasyim, Ki Bagus Hadikusumo, Kahar Muzakkir, Agus Salim dari golongan Islam."},
{"id":"TWK-3471","q":"Keberhasilan merumuskan Pancasila secara musyawarah menunjukkan bahwa para pendiri bangsa ....","opts":["mengutamakan persatuan di atas perbedaan pandangan","tidak memiliki pendirian yang teguh","mudah dipengaruhi pihak asing","tidak memahami makna dasar negara","hanya mementingkan golongannya sendiri"],"a":0,"ex":"Kompromi Piagam Jakarta hingga rumusan final adalah bukti para pendiri mengutamakan persatuan."},
{"id":"TWK-3472","q":"Dokumen yang menjadi sumber utama rumusan Pancasila dalam Pembukaan UUD 1945 adalah ....","opts":["Piagam Jakarta","naskah pidato Yamin","naskah pidato Soepomo","Maklumat Pemerintah 3 November","Traktat Sumatera"],"a":0,"ex":"Piagam Jakarta (22 Juni 1945) adalah sumber langsung rumusan Pancasila dalam Pembukaan UUD 1945."},
{"id":"TWK-3473","q":"Perbedaan Piagam Jakarta dengan Pembukaan UUD 1945 terletak pada ....","opts":["bunyi sila pertama dan sistematika pembukaan","jumlah sila Pancasila","nama negara Indonesia","tanggal penetapannya","bahasa yang digunakan"],"a":0,"ex":"Perbedaan utama: sila pertama (tujuh kata → Ketuhanan Yang Maha Esa) dan sistematika alinea pembukaan."},
{"id":"TWK-3474","q":"Pancasila sebagai dasar negara memiliki kedudukan yang ....","opts":["tertinggi sebagai sumber dari segala sumber hukum negara","sejajar dengan peraturan pemerintah","di bawah undang-undang","hanya sebagai semboyan tanpa kekuatan hukum","dapat diganti dengan keputusan presiden"],"a":0,"ex":"Pancasila adalah sumber dari segala sumber hukum (UU 12/2011) — kedudukan tertinggi dalam tata hukum Indonesia."},
{"id":"TWK-3475","q":"Hikmah yang dapat dipetik dari proses perumusan Pancasila bagi generasi muda adalah ....","opts":["perbedaan pendapat diselesaikan dengan musyawarah demi persatuan bangsa","perbedaan harus diselesaikan dengan kekerasan","kepentingan golongan di atas segalanya","musyawarah hanya membuang-buang waktu","persatuan tidak memerlukan pengorbanan"],"a":0,"ex":"Hikmahnya: beda pendapat itu wajar, selesaikan dengan musyawarah demi persatuan — teladan para pendiri bangsa."},
{"id":"TWK-3476","q":"Salah satu bukti Pancasila sebagai ideologi terbuka adalah ....","opts":["nilai dasarnya tetap sedangkan penjabarannya berkembang mengikuti zaman","seluruh nilainya dapat diganti kapan saja","tidak memiliki nilai dasar yang tetap","menolak setiap perubahan zaman","dapat diganti ideologi lain"],"a":0,"ex":"Keterbukaan: nilai dasar tetap, nilai instrumental/praksis dinamis — mis. amandemen UUD tanpa mengubah Pembukaan."},
{"id":"TWK-3477","q":"Ciri ideologi terbuka yang dimiliki Pancasila adalah ....","opts":["bersumber dari budaya bangsa sendiri dan tidak dipaksakan dari luar","menolak segala bentuk perubahan","bersifat totaliter dan kaku","hanya boleh ditafsirkan penguasa","menutup diri dari ilmu pengetahuan"],"a":0,"ex":"Pancasila terbuka karena digali dari budaya bangsa sendiri, bukan dipaksakan; ia dinamis namun berprinsip."},
{"id":"TWK-3478","q":"Contoh nyata Pancasila sebagai ideologi terbuka adalah ....","opts":["amandemen UUD 1945 tanpa mengubah Pembukaan yang memuat Pancasila","penggantian Pancasila dengan ideologi lain","penghapusan seluruh nilai Pancasila","penolakan terhadap setiap pembaruan hukum","pemberlakuan kembali UUDS 1950"],"a":0,"ex":"Amandemen 1999–2002 membuktikan keterbukaan: batang tubuh UUD berubah, nilai dasar Pancasila tetap."},
{"id":"TWK-3479","q":"Nilai dasar Pancasila contohnya adalah ....","opts":["nilai Ketuhanan, Kemanusiaan, Persatuan, Kerakyatan, dan Keadilan itu sendiri","Undang-Undang Dasar 1945","ketetapan MPR","peraturan daerah","keputusan presiden"],"a":0,"ex":"Nilai dasar = kelima sila itu sendiri; bersifat abstrak, tetap, dan menjadi cita-cita."},
{"id":"TWK-3480","q":"Contoh nilai instrumental Pancasila adalah ....","opts":["UUD 1945 sebagai penjabaran nilai dasar Pancasila","sila-sila Pancasila itu sendiri","sikap jujur dalam kehidupan sehari-hari","gotong royong membersihkan lingkungan","toleransi antarumat beragama"],"a":0,"ex":"Nilai instrumental = penjabaran nilai dasar dalam bentuk norma hukum (UUD, UU, Tap MPR); dapat berubah mengikuti zaman."},
{"id":"TWK-3481","q":"Perilaku gotong royong membersihkan lingkungan merupakan cerminan nilai Pancasila jenis ....","opts":["praksis","dasar","instrumental","kerohanian","material"],"a":0,"ex":"Gotong royong nyata di masyarakat = nilai praksis, yaitu perwujudan nilai Pancasila dalam perilaku."},
{"id":"TWK-3482","q":"Apabila nilai-nilai Pancasila dijadikan pedoman dalam mengambil keputusan sehari-hari, maka Pancasila berfungsi sebagai ....","opts":["pandangan hidup bangsa","dasar negara","ideologi tertutup","hukum pidana","peraturan daerah"],"a":0,"ex":"Pancasila sebagai pandangan hidup (way of life) = pedoman bersikap dan bertindak sehari-hari."},
{"id":"TWK-3483","q":"Pancasila sebagai dasar negara berfungsi sebagai ....","opts":["sumber dari segala sumber hukum dan pedoman penyelenggaraan negara","hiasan dalam upacara kenegaraan semata","dokumen arsip yang disimpan di museum","slogan kampanye politik belaka","aturan yang hanya mengikat rakyat kecil"],"a":0,"ex":"Sebagai dasar negara, Pancasila adalah sumber hukum tertinggi dan pedoman penyelenggaraan negara."},
{"id":"TWK-3484","q":"Pancasila sebagai ideologi nasional berarti ....","opts":["menjadi cita-cita dan arah perjuangan bangsa Indonesia","hanya menjadi milik partai politik tertentu","ideologi yang dipaksakan kepada rakyat","cita-cita yang mustahil diwujudkan","ideologi impor dari negara lain"],"a":0,"ex":"Ideologi nasional = cita-cita bersama dan arah perjuangan seluruh bangsa Indonesia."},
{"id":"TWK-3485","q":"Istilah lain dari Pancasila sebagai perjanjian luhur bangsa adalah ....","opts":["modus vivendi","staatsfundamentalnorm","way of life","weltanschauung","staatsidee"],"a":0,"ex":"Perjanjian luhur = modus vivendi: kesepakatan para pendiri bangsa sebagai dasar hidup bernegara."},
{"id":"TWK-3486","q":"Kedudukan Pembukaan UUD 1945 yang memuat Pancasila terhadap batang tubuh UUD 1945 adalah ....","opts":["lebih tinggi dan menjadi sumber tertib hukum Indonesia","sejajar tanpa perbedaan kedudukan","lebih rendah dari pasal-pasal","tidak memiliki hubungan sama sekali","hanya sebagai pengantar tanpa makna"],"a":0,"ex":"Pembukaan berkedudukan lebih tinggi; batang tubuh tidak boleh bertentangan dengannya (staatsfundamentalnorm)."},
{"id":"TWK-3487","q":"Sifat ideologi tertutup yang ditolak Pancasila contohnya adalah ....","opts":["komunisme yang kaku, dogmatis, dan menuntut kepatuhan total","demokrasi yang menghargai perbedaan","nasionalisme yang cinta tanah air","humanisme yang menjunjung kemanusiaan","sosialisme demokratis yang moderat"],"a":0,"ex":"Ideologi tertutup (mis. komunisme ortodoks) bersifat kaku-dogmatis-totaliter — berlawanan dengan keterbukaan Pancasila."},
{"id":"TWK-3488","q":"Dimensi Pancasila sebagai ideologi mencakup dimensi ....","opts":["realistis, idealis, dan normatif","ekonomis, politis, dan militer","fisik, mental, dan spiritual","individu, kelompok, dan massa","lokal, nasional, dan global"],"a":0,"ex":"Tiga dimensi ideologi Pancasila: realistis (membumi), idealis (cita-cita), normatif (pedoman)."},
{"id":"TWK-3489","q":"Dimensi realistis Pancasila berarti ....","opts":["nilai-nilainya mencerminkan kenyataan hidup bangsa Indonesia","Pancasila hanya angan-angan tanpa wujud","nilai Pancasila sulit dipahami rakyat","Pancasila terlepas dari realitas masyarakat","realitas tidak penting bagi ideologi"],"a":0,"ex":"Dimensi realistis: Pancasila digali dari dan mencerminkan realitas hidup bangsa Indonesia."},
{"id":"TWK-3490","q":"Fungsi Pancasila sebagai filter terhadap budaya asing berarti ....","opts":["budaya asing disaring: yang sesuai nilai Pancasila diterima, yang bertentangan ditolak","seluruh budaya asing harus ditolak mentah-mentah","seluruh budaya asing harus diterima sepenuhnya","bangsa Indonesia menutup diri dari dunia luar","filter budaya hanya berlaku bagi generasi tua"],"a":0,"ex":"Pancasila sebagai filter = selektif terhadap budaya asing, bukan menolak atau menerima mentah-mentah."},
{"id":"TWK-3491","q":"Pancasila sebagai jati diri bangsa Indonesia berarti ....","opts":["nilai-nilainya mencerminkan kepribadian dan karakteristik khas bangsa Indonesia","bangsa Indonesia tidak memiliki kepribadian","jati diri bangsa ditentukan negara lain","kepribadian bangsa selalu berubah-ubah","Pancasila menghapus identitas daerah"],"a":0,"ex":"Pancasila adalah cerminan kepribadian bangsa: religius, gotong royong, musyawarah — jati diri Indonesia."},
{"id":"TWK-3492","q":"Upaya melembagakan nilai-nilai Pancasila dalam kehidupan berbangsa dilakukan melalui ....","opts":["pendidikan Pancasila sejak dini hingga perguruan tinggi","menghapus pelajaran Pancasila dari kurikulum","melarang diskusi tentang Pancasila","menjadikan Pancasila sekadar hafalan","membatasi pemahaman Pancasila hanya bagi PNS"],"a":0,"ex":"Pendidikan Pancasila berjenjang adalah wahana pelembagaan nilai bagi seluruh generasi."},
{"id":"TWK-3493","q":"Badan yang bertugas membina ideologi Pancasila saat ini adalah ....","opts":["BPIP","KPK","BPK","MA","KY"],"a":0,"ex":"BPIP (Badan Pembinaan Ideologi Pancasila) dibentuk Perpres 7/2018 untuk membina ideologi Pancasila."},
{"id":"TWK-3494","q":"Pancasila dapat bertahan sebagai dasar negara karena ....","opts":["nilai-nilainya berakar pada budaya bangsa dan mampu menjawab tantangan zaman","dipaksakan dengan kekuatan militer","didukung dana asing yang besar","tidak pernah dikritik oleh siapa pun","dijaga oleh satu golongan tertentu"],"a":0,"ex":"Daya tahan Pancasila: berakar pada budaya bangsa + bersifat terbuka menjawab tantangan zaman."},
{"id":"TWK-3495","q":"Ancaman terbesar terhadap Pancasila sebagai ideologi negara di era globalisasi adalah ....","opts":["masuknya ideologi asing yang bertentangan tanpa penyaringan","kemajuan teknologi informasi","pertukaran pelajar ke luar negeri","perdagangan internasional","pariwisata mancanegara"],"a":0,"ex":"Ancaman utama: ideologi asing (radikalisme, liberalisme ekstrem) yang masuk tanpa disaring nilai Pancasila."},
{"id":"TWK-3496","q":"Sikap yang tepat dalam menghadapi ideologi asing menurut Pancasila adalah ....","opts":["selektif: mengambil yang baik dan menolak yang bertentangan dengan Pancasila","menerima seluruhnya tanpa pertimbangan","menolak seluruhnya tanpa kecuali","acuh tak acuh dan tidak peduli","menyerahkan sepenuhnya kepada pemerintah"],"a":0,"ex":"Sikap Pancasila: selektif-adaptif — ambil yang baik, tolak yang bertentangan."},
{"id":"TWK-3497","q":"Pancasila sebagai staatsfundamentalnorm berarti ....","opts":["norma fundamental negara yang menjadi sumber tertib hukum Indonesia","aturan tentang lambang negara semata","norma yang hanya berlaku saat darurat","hukum pidana tertinggi di Indonesia","peraturan tentang kepegawaian negara"],"a":0,"ex":"Staatsfundamentalnorm (Notonagoro): Pancasila sebagai norma fundamental sumber tertib hukum."},
{"id":"TWK-3498","q":"Hierarki nilai Pancasila menurut Notonagoro terdiri atas nilai ....","opts":["material, vital, dan kerohanian","dasar, instrumental, dan praksis","hukum, moral, dan adat","individu, sosial, dan negara","primer, sekunder, dan tersier"],"a":0,"ex":"Notonagoro membagi nilai: material (kebendaan), vital (kegunaan), kerohanian (kebenaran, keindahan, moral, religius)."},
{"id":"TWK-3499","q":"Nilai kerohanian dalam hierarki Notonagoro yang berkaitan dengan sila pertama Pancasila adalah nilai ....","opts":["religius","kebenaran","keindahan","moral","vital"],"a":0,"ex":"Nilai kerohanian meliputi kebenaran, keindahan, moral (kebaikan), dan religius — sila pertama berakar pada nilai religius."},
{"id":"TWK-3500","q":"Keunggulan Pancasila dibandingkan ideologi lain menurut para pendiri bangsa adalah ....","opts":["digali dari nilai-nilai luhur bangsa Indonesia sendiri","diimpor dari negara yang paling maju","dirumuskan dalam waktu yang sangat singkat","tidak memiliki nilai yang pasti","disusun oleh satu orang jenius"],"a":0,"ex":"Keunggulan Pancasila: bukan ideologi impor, melainkan digali dari bumi dan budaya Indonesia sendiri."},
{"id":"TWK-3501","q":"Lambang negara Indonesia yang mencerminkan sila-sila Pancasila adalah ....","opts":["Garuda Pancasila","Banteng","Pohon beringin","Padi dan kapas","Bintang"],"a":0,"ex":"Garuda Pancasila ditetapkan sebagai lambang negara Indonesia (PP 66/1951)."},
{"id":"TWK-3502","q":"Jumlah helai bulu pada sayap Garuda Pancasila adalah ....","opts":["17 helai","8 helai","19 helai","45 helai","21 helai"],"a":0,"ex":"17 helai bulu di tiap sayap melambangkan tanggal 17 kemerdekaan Indonesia."},
{"id":"TWK-3503","q":"Jumlah helai bulu pada ekor Garuda Pancasila adalah ....","opts":["8 helai","17 helai","19 helai","45 helai","12 helai"],"a":0,"ex":"8 helai bulu ekor melambangkan bulan ke-8 (Agustus)."},
{"id":"TWK-3504","q":"Jumlah helai bulu pada leher Garuda Pancasila adalah ....","opts":["45 helai","17 helai","8 helai","19 helai","50 helai"],"a":0,"ex":"45 helai bulu leher melambangkan tahun 1945 — lengkap 17-8-1945."},
{"id":"TWK-3505","q":"Makna jumlah bulu Garuda Pancasila (17-8-45) adalah ....","opts":["tanggal proklamasi kemerdekaan Indonesia 17 Agustus 1945","jumlah sila Pancasila","jumlah provinsi pertama Indonesia","jumlah anggota PPKI","jumlah huruf semboyan Bhinneka Tunggal Ika"],"a":0,"ex":"17 helai sayap, 8 helai ekor, 45 helai leher = 17 Agustus 1945."},
{"id":"TWK-3506","q":"Perisai yang dikalungkan pada dada Garuda Pancasila melambangkan ....","opts":["pertahanan dan perjuangan bangsa Indonesia","kekuasaan raja-raja Nusantara","perisai perang kerajaan Majapahit","alat pertanian masyarakat desa","perisai para pahlawan kemerdekaan"],"a":0,"ex":"Perisai dada Garuda melambangkan pertahanan dan perjuangan bangsa Indonesia."},
{"id":"TWK-3507","q":"Cahaya yang memancar dari bintang pada perisai Garuda Pancasila melambangkan ....","opts":["cahaya rohani dari Tuhan kepada setiap manusia","cahaya lampu penerangan jalan","kilauan emas perisai","cahaya matahari pagi hari","tidak memiliki makna khusus"],"a":0,"ex":"Bintang sila pertama memancarkan cahaya = cahaya rohani Ketuhanan bagi manusia."},
{"id":"TWK-3508","q":"Lambang sila kedua pada perisai Garuda Pancasila adalah ....","opts":["rantai","bintang","pohon beringin","kepala banteng","padi dan kapas"],"a":0,"ex":"Rantai = sila kedua; mata rantai segi empat (laki-laki) dan lingkaran (perempuan) melambangkan hubungan manusia."},
{"id":"TWK-3509","q":"Lambang sila ketiga pada perisai Garuda Pancasila adalah ....","opts":["pohon beringin","bintang","rantai","kepala banteng","padi dan kapas"],"a":0,"ex":"Pohon beringin = sila ketiga; beringin yang rindang melambangkan persatuan dan pengayoman."},
{"id":"TWK-3510","q":"Lambang sila keempat pada perisai Garuda Pancasila adalah ....","opts":["kepala banteng","bintang","rantai","pohon beringin","padi dan kapas"],"a":0,"ex":"Kepala banteng = sila keempat; banteng yang suka berkumpul melambangkan musyawarah."},
{"id":"TWK-3511","q":"Lambang sila kelima pada perisai Garuda Pancasila adalah ....","opts":["padi dan kapas","bintang","rantai","pohon beringin","kepala banteng"],"a":0,"ex":"Padi dan kapas = sila kelima; melambangkan pangan dan sandang — kemakmuran dan keadilan sosial."},
{"id":"TWK-3512","q":"Semboyan yang tertera pada pita yang dicengkeram Garuda Pancasila adalah ....","opts":["Bhinneka Tunggal Ika","Tut Wuri Handayani","Bhineka Tunggal Ika Tan Hana Dharma Mangrwa","Ing Ngarso Sung Tulodo","Bersatu Kita Teguh"],"a":0,"ex":"Pita Garuda bertuliskan 'Bhinneka Tunggal Ika' — berbeda-beda tetapi tetap satu jua."},
{"id":"TWK-3513","q":"Semboyan Bhinneka Tunggal Ika yang tertera pada Garuda Pancasila berasal dari kitab ....","opts":["Sutasoma","Negarakertagama","Pararaton","Arjunawiwaha","Bharatayuddha"],"a":0,"ex":"Bhinneka Tunggal Ika dari kitab Sutasoma karya Mpu Tantular zaman Majapahit."},
{"id":"TWK-3514","q":"Arti semboyan Bhinneka Tunggal Ika pada lambang Garuda Pancasila adalah ....","opts":["berbeda-beda tetapi tetap satu jua","bersatu kita teguh bercerai kita runtuh","di depan memberi teladan","bersama kita bisa","persatuan dalam keberagaman suku Jawa"],"a":0,"ex":"Bhinneka Tunggal Ika = berbeda-beda tetapi tetap satu — semboyan persatuan dalam kebinekaan."},
{"id":"TWK-3515","q":"Warna kuning emas pada Garuda Pancasila melambangkan ....","opts":["keagungan dan kejayaan bangsa Indonesia","kekayaan hasil tambang Indonesia","warna kesukaan para pendiri bangsa","lambang kerajaan Hindu-Buddha","tidak memiliki makna khusus"],"a":0,"ex":"Kuning emas = keagungan, keluhuran, dan kejayaan bangsa Indonesia."},
{"id":"TWK-3516","q":"Sayap Garuda Pancasila yang membentang lebar melambangkan ....","opts":["kesiapan dan kekuatan bangsa menjaga kedaulatan negara","burung yang sedang terbang tinggi","kebebasan tanpa batas","kekuasaan yang absolut","tidak memiliki makna khusus"],"a":0,"ex":"Sayap membentang gagah = kesiapan dan kekuatan bangsa menjaga kedaulatan negara."},
{"id":"TWK-3517","q":"Lambang Garuda Pancasila disempurnakan oleh pelukis ....","opts":["Dullah","S. Sudjojono","Affandi","Basuki Abdullah","Raden Saleh"],"a":0,"ex":"Rancangan Sultan Hamid II disempurnakan pelukis Dullah atas perintah Presiden Soekarno."},
{"id":"TWK-3518","q":"Garuda Pancasila ditetapkan sebagai lambang negara melalui ....","opts":["PP Nomor 66 Tahun 1951","UUD 1945","Ketetapan MPR","UU Nomor 24 Tahun 2009","Keputusan Presiden 24/2016"],"a":0,"ex":"PP 66/1951 menetapkan Garuda Pancasila sebagai lambang negara (disempurnakan UU 24/2009)."},
{"id":"TWK-3519","q":"Burung garuda dalam mitologi yang menjadi inspirasi lambang negara dikenal sebagai ....","opts":["kendaraan Dewa Wisnu yang gagah berani","burung pemakan bangkai","hewan kurban para raja","burung peliharaan rakyat jelata","lambang keserakahan penguasa"],"a":0,"ex":"Garuda adalah kendaraan Dewa Wisnu — simbol kegagahan, kekuatan, dan keberanian."},
{"id":"TWK-3520","q":"Garis tebal melintang pada perisai Garuda Pancasila melambangkan ....","opts":["garis khatulistiwa yang melintasi Indonesia","batas wilayah Indonesia","sungai-sungai besar di Indonesia","jalan raya trans Jawa","patahan lempeng bumi"],"a":0,"ex":"Garis melintang pada perisai melambangkan khatulistiwa yang membelah kepulauan Indonesia."},
{"id":"TWK-3521","q":"Jumlah sudut pada bintang lambang sila pertama Garuda Pancasila adalah ....","opts":["lima","tujuh","delapan","sembilan","tiga"],"a":0,"ex":"Bintang bersudut lima melambangkan lima sila Pancasila dengan cahaya ketuhanan."},
{"id":"TWK-3522","q":"Rantai yang tidak terputus pada lambang sila kedua Garuda Pancasila melambangkan ....","opts":["hubungan antar manusia yang saling terkait dan berkesinambungan","rantai perbudakan di masa penjajahan","persatuan kaum buruh dan tani","hubungan Indonesia dengan negara lain","mata uang logam zaman dahulu"],"a":0,"ex":"Rantai tak terputus = hubungan antar manusia yang saling terkait lintas generasi."},
{"id":"TWK-3523","q":"Akar pohon beringin yang menggantung pada lambang sila ketiga melambangkan ....","opts":["tempat berteduh dan berlindung seluruh rakyat Indonesia","akar penjajahan yang harus dicabut","pohon yang sudah tua dan lapuk","tidak memiliki makna khusus","sistem feodalisme masa lalu"],"a":0,"ex":"Beringin rindang dengan akar menggantung = pengayoman dan tempat berlindung seluruh bangsa."},
{"id":"TWK-3524","q":"Penggunaan Garuda Pancasila diatur dalam undang-undang, yaitu ....","opts":["UU Nomor 24 Tahun 2009 tentang Bendera, Bahasa, dan Lambang Negara","UU Nomor 12 Tahun 2011","UU Nomor 5 Tahun 2014","UU Nomor 20 Tahun 2003","UU Nomor 39 Tahun 1999"],"a":0,"ex":"UU 24/2009 mengatur bendera, bahasa, lambang negara, dan lagu kebangsaan."},
{"id":"TWK-3525","q":"Sikap yang tepat terhadap lambang negara Garuda Pancasila adalah ....","opts":["menghormati dan menjaga kehormatannya sebagai simbol negara","menggunakannya sebagai motif kaos seenaknya","memodifikasi bentuknya sesuai selera pribadi","memperjualbelikan replika tanpa aturan","mengabaikannya dalam upacara resmi"],"a":0,"ex":"Garuda Pancasila wajib dihormati; penggunaannya diatur undang-undang dan tidak boleh direndahkan."},
{"id":"TWK-3526","q":"Pemberontakan G30S/PKI tahun 1965 merupakan pengkhianatan terhadap Pancasila karena ....","opts":["berupaya mengganti Pancasila dengan ideologi komunisme","memperjuangkan kemerdekaan Indonesia","menuntut kesejahteraan rakyat kecil","melakukan musyawarah nasional","membela nilai-nilai Pancasila"],"a":0,"ex":"G30S/PKI berupaya mengganti Pancasila dengan komunisme — pengkhianatan terhadap dasar negara."},
{"id":"TWK-3527","q":"Gerakan DI/TII yang ingin mendirikan negara Islam Indonesia bertentangan dengan Pancasila sila ....","opts":["pertama","kedua","ketiga","keempat","kelima"],"a":0,"ex":"DI/TII menolak Ketuhanan Yang Maha Esa yang merangkul semua agama — pelanggaran sila pertama."},
{"id":"TWK-3528","q":"Pemberontakan PRRI/Permesta pada 1958 bertentangan dengan Pancasila terutama sila ....","opts":["ketiga","pertama","kedua","keempat","kelima"],"a":0,"ex":"PRRI/Permesta mengangkat senjata melawan pemerintah sah — merongrong persatuan Indonesia (sila ketiga)."},
{"id":"TWK-3529","q":"Aksi terorisme yang mengatasnamakan agama merupakan pelanggaran terhadap Pancasila sila ....","opts":["pertama dan kedua","ketiga dan keempat","keempat dan kelima","pertama saja","kelima saja"],"a":0,"ex":"Terorisme menodai nilai Ketuhanan (sila 1) sekaligus merampas hak hidup manusia (sila 2)."},
{"id":"TWK-3530","q":"Seorang pejabat negara melakukan korupsi berjamaah. Perilaku tersebut mengkhianati Pancasila sila ....","opts":["kelima","pertama","kedua","ketiga","keempat"],"a":0,"ex":"Korupsi merampas hak rakyat atas keadilan dan kesejahteraan — pengkhianatan sila kelima."},
{"id":"TWK-3531","q":"Praktik politik uang dalam pemilihan umum bertentangan dengan Pancasila sila ....","opts":["keempat","pertama","kedua","ketiga","kelima"],"a":0,"ex":"Politik uang merusak musyawarah dan kedaulatan rakyat yang jujur-adil — pelanggaran sila keempat."},
{"id":"TWK-3532","q":"Seorang siswa bernama Andi selalu membantu temannya yang kesulitan tanpa memandang suku dan agama temannya. Sikap Andi mencerminkan pengamalan Pancasila sila ....","opts":["kedua","pertama","ketiga","keempat","kelima"],"a":0,"ex":"Menolong tanpa memandang suku/agama = memanusiakan manusia — sila kedua."},
{"id":"TWK-3533","q":"Dalam sebuah rapat RT, sebagian warga memaksakan kehendak dengan berteriak dan mengancam warga lain. Perilaku tersebut tidak sesuai dengan sila Pancasila, yaitu ....","opts":["keempat","pertama","kedua","ketiga","kelima"],"a":0,"ex":"Intimidasi dalam rapat meniadakan musyawarah yang beradab — pelanggaran sila keempat."},
{"id":"TWK-3534","q":"Bu Sari seorang pedagang pasar yang selalu jujur dalam timbangan dan tidak pernah mengurangi hak pembeli. Perilaku Bu Sari selaras dengan Pancasila sila ....","opts":["kelima","pertama","kedua","ketiga","keempat"],"a":0,"ex":"Kejujuran timbangan adalah keadilan dalam berdagang — pengamalan sila kelima."},
{"id":"TWK-3535","q":"Sekelompok pemuda melakukan sweeping terhadap rumah ibadah agama lain dengan dalih menjaga moral. Tindakan tersebut melanggar Pancasila sila ....","opts":["pertama","kedua","ketiga","keempat","kelima"],"a":0,"ex":"Sweeping rumah ibadah adalah intoleransi — pelanggaran kebebasan beragama (sila pertama)."},
{"id":"TWK-3536","q":"Pak Budi menolak menjual tanahnya kepada orang dari suku tertentu meski harganya tinggi. Sikap Pak Budi bertentangan dengan Pancasila sila ....","opts":["ketiga","pertama","kedua","keempat","kelima"],"a":0,"ex":"Diskriminasi suku dalam jual beli merusak persatuan — pelanggaran sila ketiga."},
{"id":"TWK-3537","q":"Seorang kepala desa membangun jalan desa melalui gotong royong seluruh warga tanpa membedakan latar belakang. Kebijakan tersebut mencerminkan Pancasila sila ....","opts":["ketiga dan kelima","pertama dan kedua","kedua dan keempat","pertama dan kelima","ketiga saja"],"a":0,"ex":"Gotong royong lintas latar belakang = persatuan (sila 3) demi kesejahteraan bersama (sila 5)."},
{"id":"TWK-3538","q":"Siswa yang mencontek saat ujian lalu berdoa agar tidak ketahuan menunjukkan pemahaman sila pertama Pancasila yang ....","opts":["pengamalan sila pertama yang keliru dan tidak jujur","pengamalan sila pertama yang sempurna","kecerdasan spiritual yang tinggi","ketaatan beragama yang patut dicontoh","keseimbangan iman dan ilmu"],"a":0,"ex":"Berdoa agar kejahatan tidak ketahuan adalah pemahaman keliru — sila pertama menuntut kejujuran."},
{"id":"TWK-3539","q":"Seorang anggota DPR tertangkap menerima suap untuk meloloskan undang-undang. Kasus tersebut mencoreng Pancasila sila ....","opts":["kelima dan keempat","pertama dan kedua","kedua dan ketiga","pertama dan ketiga","ketiga dan kelima"],"a":0,"ex":"Suap merusak amanah perwakilan (sila 4) dan merampas keadilan rakyat (sila 5)."},
{"id":"TWK-3540","q":"Gerakan radikal yang menyebarkan ujaran kebencian antarumat beragama bertujuan memecah belah bangsa. Gerakan tersebut mengancam Pancasila sila ....","opts":["pertama dan ketiga","kedua dan keempat","keempat dan kelima","kedua saja","kelima saja"],"a":0,"ex":"Ujaran kebencian antaragama menyerang kerukunan beragama (sila 1) dan persatuan (sila 3)."},
{"id":"TWK-3541","q":"Seorang nelayan menemukan dompet berisi uang lalu mengembalikannya kepada pemiliknya. Perbuatan tersebut mencerminkan sila Pancasila, yaitu ....","opts":["kedua","pertama","ketiga","keempat","kelima"],"a":0,"ex":"Kejujuran mengembalikan milik orang lain adalah akhlak kemanusiaan yang beradab — sila kedua."},
{"id":"TWK-3542","q":"Paham yang menganggap Pancasila sudah tidak relevan dan harus diganti ideologi lain harus disikapi dengan ....","opts":["meneguhkan pemahaman dan pengamalan Pancasila dalam kehidupan berbangsa","membiarkan paham tersebut berkembang bebas","mengganti Pancasila dengan ideologi yang ditawarkan","melakukan kekerasan terhadap penganut paham itu","menghapus Pancasila dari seluruh dokumen negara"],"a":0,"ex":"Sikap tepat: meneguhkan pemahaman dan pengamalan Pancasila, bukan kekerasan atau pembiaran."},
{"id":"TWK-3543","q":"Seorang camat menolak usulan warga dengan alasan 'sudah keputusan saya, tidak bisa diganggu gugat'. Sikap camat tersebut bertentangan dengan sila ....","opts":["keempat","pertama","kedua","ketiga","kelima"],"a":0,"ex":"Menolak aspirasi warga secara otoriter meniadakan musyawarah — pelanggaran sila keempat."},
{"id":"TWK-3544","q":"Program vaksinasi massal gratis bagi seluruh rakyat tanpa terkecuali mencerminkan Pancasila sila ....","opts":["kelima","pertama","kedua","ketiga","keempat"],"a":0,"ex":"Layanan kesehatan gratis merata = keadilan sosial bagi seluruh rakyat — sila kelima."},
{"id":"TWK-3545","q":"Seorang pelajar mengikuti upacara bendera dengan khidmat dan menyanyikan Indonesia Raya dengan sungguh-sungguh. Sikap tersebut menumbuhkan nilai Pancasila sila ....","opts":["ketiga","pertama","kedua","keempat","kelima"],"a":0,"ex":"Khidmat dalam upacara bendera menumbuhkan nasionalisme dan persatuan — sila ketiga."},
{"id":"TWK-3546","q":"Tindakan main hakim sendiri terhadap terduga pelaku kejahatan bertentangan dengan Pancasila sila ....","opts":["kedua","pertama","ketiga","keempat","kelima"],"a":0,"ex":"Main hakim sendiri merampas hak asasi terduga dan merendahkan martabat manusia — pelanggaran sila kedua."},
{"id":"TWK-3547","q":"Seorang ibu mengajarkan anaknya untuk selalu bersyukur dan berdoa sebelum makan. Pendidikan tersebut menanamkan Pancasila sila ....","opts":["pertama","kedua","ketiga","keempat","kelima"],"a":0,"ex":"Menanamkan syukur dan doa sejak dini adalah pendidikan sila pertama di keluarga."},
{"id":"TWK-3548","q":"Dalam penyelesaian sengketa tanah, kedua belah pihak sepakat berdamai melalui mediasi perangkat desa. Cara tersebut sejalan dengan Pancasila sila ....","opts":["keempat","pertama","kedua","ketiga","kelima"],"a":0,"ex":"Mediasi damai adalah musyawarah — penyelesaian sengketa ala sila keempat."},
{"id":"TWK-3549","q":"Seorang pengusaha sukses menyisihkan sebagian keuntungannya untuk beasiswa anak kurang mampu. Tindakan tersebut mengamalkan Pancasila sila ....","opts":["kelima","pertama","kedua","ketiga","keempat"],"a":0,"ex":"Berbagi keuntungan untuk pendidikan kaum dhuafa = keadilan sosial — sila kelima."},
{"id":"TWK-3550","q":"Pesan terpenting Pancasila bagi generasi muda Indonesia adalah ....","opts":["mengamalkan nilai-nilainya dalam kehidupan sehari-hari, bukan sekadar menghafal","cukup menghafal bunyi lima silanya di luar kepala","Pancasila hanya penting saat ujian sekolah","nilai Pancasila sudah ketinggalan zaman","generasi muda tidak perlu memahami Pancasila"],"a":0,"ex":"Pesan utama: Pancasila hidup dalam pengamalan sehari-hari, bukan sekadar hafalan."},
];
